INSERT INTO `career_roadmaps` VALUES (1,1,1,'Build Basic Electrical Knowledge','Learn electrical fundamentals such as voltage, current, resistance, power, AC/DC basics, electrical symbols, circuits, wires, cables and common electrical components.'),(2,1,2,'Learn Electrical Safety','Develop safe working practices including PPE, isolation of power, earthing, avoiding electric shock, safe use of tools, basic fire safety and emergency procedures.'),(3,1,3,'Develop Practical Wiring Skills','Practice domestic wiring, switches, sockets, lighting circuits, distribution boards, cable selection, connections and basic fault identification under proper supervision.'),(4,1,4,'Learn Testing and Fault Finding','Learn to use electrical testing instruments such as a multimeter and other appropriate testing equipment to identify common wiring, continuity, insulation and circuit faults safely.'),(5,1,5,'Complete Formal Vocational Training','Consider the DGT Craftsmen Training Scheme Electrician trade through an appropriate ITI. The current DGT CTS Electrician trade is a two-year training programme at NSQF Level 4.'),(6,1,6,'Gain Supervised Workplace Experience','Work under an experienced electrician, contractor or suitable workplace to develop practical experience in installations, maintenance, repairs, customer work and safe working procedures.'),(7,1,7,'Develop Advanced Electrical Skills','Progress into areas such as electrical maintenance, motors, control panels, electrical equipment, troubleshooting and other specializations relevant to the worker’s career goals.'),(8,1,8,'Build Professional Experience and Reputation','Maintain a portfolio of completed work, improve customer communication, follow safety standards, keep records of jobs and develop a reliable professional reputation.'),(9,1,9,'Move Toward Independent Work or Business','After gaining sufficient skills and experience, take suitable independent service work or develop an electrical service business while following applicable legal, safety and local requirements.'),(10,2,1,'Learn Plumbing Fundamentals','Understand plumbing systems, water supply, drainage, common plumbing materials, pipe types, fittings, valves, tools, measurements and basic plumbing terminology.'),(11,2,2,'Learn Tool Handling and Workplace Safety','Learn safe use of plumbing hand tools and equipment, PPE, hazard identification, first aid, electrical safety around plumbing work, fire safety and safe disposal of waste materials.'),(12,2,3,'Develop Basic Pipe Fitting Skills','Practice measuring, marking, cutting, threading and joining pipes and learn how different fittings, joints and connections are used in plumbing installations.'),(13,2,4,'Learn Water Supply and Sanitary Installation','Develop practical skills in installing and repairing hot and cold water pipelines, taps, valves, sanitary fixtures and related plumbing connections.'),(14,2,5,'Learn Drainage and Waste-Pipe Maintenance','Learn installation, maintenance, repair and reconditioning of waste and drainage pipe systems, including identifying leaks, blockages and common faults.'),(15,2,6,'Complete Formal Plumbing Training','Consider the DGT Craftsmen Training Scheme Plumber trade. The current CTS Plumber programme is one year with 1200 hours of training and has an entry qualification of 8th class.'),(16,2,7,'Gain Supervised Practical Experience','Work with an experienced plumber, contractor or plumbing service provider to gain practical experience in residential, commercial or construction-related plumbing work.'),(17,2,8,'Build Specialized Plumbing Skills','Develop additional skills according to career goals, such as sanitary installation, water-system maintenance, building plumbing, repair work, or other relevant plumbing specializations.'),(18,2,9,'Start Independent Plumbing Work','After gaining sufficient practical experience, take suitable independent service work, build a customer base, maintain a portfolio of completed work and consider developing a plumbing service business while following applicable local requirements.'),(19,3,1,'Learn Basic Woodworking Fundamentals','Understand different types of wood and wood-based materials, grain direction, measurements, common carpentry terminology, basic drawings and the purpose of common hand tools.'),(20,3,2,'Learn Tool Handling and Workshop Safety','Learn safe handling of saws, chisels, planes, drills and other carpentry tools, along with PPE, dust control, safe work practices and proper maintenance of tools.'),(21,3,3,'Develop Measuring, Marking and Cutting Skills','Practice accurate measuring, marking and cutting of wooden pieces using appropriate tools while checking dimensions with measuring tapes, squares and other measuring instruments.'),(22,3,4,'Learn Wood Joints and Assembly','Develop practical skills in making common joints such as mortise and tenon, dovetail and half-lap joints, followed by assembling components using suitable methods such as screws, nails, dowels, glue and other fittings.'),(23,3,5,'Learn Furniture and Woodwork Construction','Practice making and assembling basic furniture and wooden articles according to measurements, drawings or samples while maintaining accuracy and structural strength.'),(24,3,6,'Develop Finishing and Repair Skills','Learn surface preparation, sanding, basic finishing and polishing techniques, installation of suitable fittings, and repair or replacement of damaged wooden components.'),(25,3,7,'Complete Formal Woodworking Training','Consider an appropriate DGT vocational training pathway such as Wood Work Technician where available. The training covers practical woodworking, tools, measurements, joints, assembly, repairs and related occupational skills.'),(26,3,8,'Gain Supervised Practical Experience','Work with an experienced carpenter, furniture workshop, contractor or construction team to gain practical experience in furniture work, doors, windows, frames, fixtures, repairs and other relevant projects.'),(27,3,9,'Specialize and Build Independent Work','Develop a specialization such as furniture making, construction carpentry, interior woodwork or repair services. Build a portfolio, establish customer relationships and gradually move toward independent work or a carpentry business while following applicable local requirements.'),(28,4,1,'Learn Basic Painting Fundamentals','Understand different types of paints, primers, thinners, coatings, brushes, rollers, spray equipment and basic colour concepts. Learn how different surfaces require different preparation and painting methods.'),(29,4,2,'Learn Workplace Safety','Learn safe handling and storage of paints, solvents and other materials, proper ventilation, PPE, ladder safety, protection from fumes and dust, and safe working practices at residential and commercial sites.'),(30,4,3,'Develop Surface Preparation Skills','Learn how to clean, scrape, sand, repair cracks and holes, remove loose paint and prepare surfaces before applying primer or paint. Proper preparation should become a core part of every painting job.'),(31,4,4,'Learn Basic Painting Techniques','Practice applying primer and paint using brushes and rollers while learning how to achieve even coverage, clean edges, consistent coats and proper drying between coats.'),(32,4,5,'Learn Advanced Application Methods','Develop skills in spray painting and other suitable application techniques. Learn how to select appropriate tools and techniques for walls, ceilings, wood, metal and other common surfaces.'),(33,4,6,'Develop Decorative and Finishing Skills','Learn colour combinations, texture and decorative finishing techniques, along with detailed finishing work required to produce clean and professional results.'),(34,4,7,'Gain Professional Training and Practical Experience','Consider relevant vocational or skill-development training where available and gain supervised practical experience with an experienced painter, contractor or painting service provider.'),(35,4,8,'Build a Professional Painting Portfolio','Document completed projects, record the type of work performed, improve estimation and material-planning skills, communicate clearly with customers and develop a reputation for quality and reliable work.'),(36,4,9,'Start Independent Painting Services','After gaining sufficient practical experience, begin taking suitable independent painting jobs, develop repeat customers, manage quotations and material costs, and gradually build an independent painting service or small business.'),(37,5,1,'Learn Basic Sewing Fundamentals','Learn how sewing machines, needles, threads, fabrics and basic sewing tools work. Develop basic skills such as straight stitching, seam joining, hemming and safe machine operation.'),(38,5,2,'Learn Fabric and Measurement Basics','Understand common fabric types, fabric behaviour, grain direction, measurements, seam allowances and how fabric selection affects garment construction.'),(39,5,3,'Develop Cutting and Pattern-Making Skills','Learn accurate body measurement, pattern preparation, fabric marking and cutting. Practice converting measurements into suitable garment patterns while minimizing fabric wastage.'),(40,5,4,'Learn Garment Construction','Progress from simple garments to more complex construction techniques, including stitching different garment components, attaching sleeves and collars, installing zippers and completing hems and finishing.'),(41,5,5,'Develop Alteration and Repair Skills','Learn to alter garment size and fit, repair seams, replace zippers and buttons, adjust hems and perform common clothing repairs according to customer requirements.'),(42,5,6,'Develop Advanced Tailoring and Design Skills','Improve fitting, pattern modification, garment design and finishing skills. Explore specialized areas such as ethnic wear, formal wear, childrenswear or custom garments according to career interests.'),(43,5,7,'Gain Professional Training and Practical Experience','Consider relevant vocational or skill-development training and gain practical experience by working with an experienced tailor, boutique, garment unit or clothing business.'),(44,5,8,'Build a Tailoring Portfolio and Customer Base','Create samples of completed garments, maintain records of measurements and orders, improve customer communication, learn basic pricing and material estimation, and build a portfolio of work.'),(45,5,9,'Start Independent Tailoring or Boutique Work','After developing sufficient technical and customer-service skills, begin taking independent orders, offer alteration and custom-tailoring services, develop repeat customers and gradually establish a home-based or commercial tailoring business.'),(46,6,1,'Learn Beauty and Personal Care Fundamentals','Understand basic skin, hair and personal-care concepts, hygiene practices, common beauty products, tools and equipment, and safe preparation of a client before providing a service.'),(47,6,2,'Learn Hygiene, Sanitation and Client Safety','Develop proper hand hygiene, tool cleaning and disinfection practices, safe product handling, workstation hygiene, basic precautions and client consultation practices to reduce avoidable risks during beauty services.'),(48,6,3,'Develop Basic Beauty Service Skills','Practice suitable basic services such as cleansing, basic skincare, hair care, threading or other services according to training and competency. Learn how to select products and techniques according to the client and service.'),(49,6,4,'Develop Hair and Styling Skills','Learn basic hair preparation, blow-drying, styling and suitable finishing techniques. Gradually develop skills in different hairstyles and occasion-based styling according to professional training.'),(50,6,5,'Develop Makeup Skills','Learn skin preparation, basic makeup application, colour matching, foundation and concealer application, eye makeup, lip makeup and appropriate product selection. Practice creating clean and suitable looks for different occasions.'),(51,6,6,'Build Advanced and Specialized Skills','Develop specialized skills according to career goals, such as bridal makeup, occasion makeup, hairstyling, skincare services or other beauty specializations. Continue practising techniques and maintaining a portfolio.'),(52,6,7,'Complete Relevant Training and Gain Practical Experience','Consider appropriate vocational or professional beauty training and gain supervised practical experience in a salon, beauty studio or other suitable workplace. Build competence before independently offering specialized services.'),(53,6,8,'Build a Professional Portfolio and Client Base','Document suitable completed work, maintain client records where appropriate, improve consultation and communication skills, learn service pricing and appointment management, and develop a professional portfolio.'),(54,6,9,'Start Independent Beauty or Makeup Services','After developing sufficient skills and practical experience, provide suitable independent beauty or makeup services, develop repeat customers and consider a home-based studio, mobile service or beauty business while following applicable local requirements.'),(55,7,1,'Learn Basic Electrical and Appliance Fundamentals','Understand basic electricity, circuits, electrical components, appliance parts, wiring diagrams, common tools and the basic operating principles of household electrical appliances.'),(56,7,2,'Learn Workshop Safety and Electrical Safety','Learn safe isolation of electrical power, use of PPE, safe handling of tools and test instruments, fire and electrical safety, and precautions when working around refrigerants, compressors and other appliance components.'),(57,7,3,'Develop Testing and Diagnostic Skills','Learn to identify common appliance faults, inspect components, read basic wiring diagrams and use suitable testing instruments to diagnose electrical and mechanical problems safely.'),(58,7,4,'Learn Air-Conditioner Servicing','Develop practical skills in AC installation support, cleaning, routine servicing, filters, electrical connections, basic troubleshooting and identification of common cooling and airflow problems.'),(59,7,5,'Learn Refrigeration and Cooling-System Fundamentals','Understand the basic refrigeration cycle and the function of components such as compressors, condensers, evaporators, expansion devices and related controls. Learn appropriate safe handling practices for refrigeration systems.'),(60,7,6,'Develop Appliance Repair Skills','Learn systematic troubleshooting and repair practices for suitable household appliances, including identifying faulty electrical, mechanical and control components and replacing appropriate parts safely.'),(61,7,7,'Complete Relevant Technical Training and Gain Experience','Consider appropriate technical or vocational training in refrigeration, air conditioning, electrical or appliance servicing and gain supervised practical experience with an experienced technician or service organization.'),(62,7,8,'Build Specialized Technical Skills','Choose a specialization such as air-conditioning service, refrigeration, appliance repair, installation or maintenance. Continue developing diagnostic skills and maintain records of completed service work.'),(63,7,9,'Start Independent Technician Services','After gaining sufficient training and practical experience, take suitable independent repair and maintenance jobs, develop a customer base, manage service records and gradually establish an appliance or AC service business while following applicable safety and regulatory requirements.'),(64,8,1,'Learn Automobile Fundamentals','Understand the basic systems of an automobile, including the engine, transmission, braking system, steering, suspension, fuel system, cooling system and electrical system.'),(65,8,2,'Learn Workshop Tools and Safety','Learn correct use and maintenance of hand tools, measuring instruments and workshop equipment. Develop safe lifting, PPE, fire-safety and vehicle-handling practices.'),(66,8,3,'Develop Basic Vehicle Servicing Skills','Learn routine maintenance tasks such as checking fluids, filters, belts, batteries, tyres and other serviceable components according to the vehicle manufacturer requirements.'),(67,8,4,'Learn Engine and Mechanical Systems','Develop practical understanding of engine operation and mechanical components. Learn systematic inspection and basic repair procedures under appropriate supervision.'),(68,8,5,'Learn Vehicle Electrical and Diagnostic Skills','Develop basic automotive electrical skills and learn to use suitable diagnostic and testing equipment to identify electrical and electronic faults safely.'),(69,8,6,'Develop Advanced Repair Skills','Progress into more complex troubleshooting and repair work involving engine systems, braking, steering, suspension, transmission and other vehicle systems according to training and competency.'),(70,8,7,'Complete Formal Automotive Training and Gain Experience','Consider an appropriate automotive vocational training pathway and gain supervised workplace experience in an automobile workshop, service centre or garage.'),(71,8,8,'Choose a Mechanical Specialization','Develop deeper expertise in an area such as engine repair, automotive electrical systems, diagnostics, two-wheeler servicing, four-wheeler servicing or another suitable specialization.'),(72,8,9,'Build an Independent Garage or Service Career','After gaining sufficient practical experience, develop a professional customer base, maintain service records, estimate repair costs accurately and progress toward independent mechanical work or operating a workshop.'),(73,9,1,'Learn Refrigeration Fundamentals','Understand the basic refrigeration cycle and the purpose of major components such as the compressor, condenser, evaporator, expansion device, thermostat and refrigerant circuit.'),(74,9,2,'Learn Electrical and Refrigeration Safety','Learn safe electrical isolation, PPE, safe handling of tools and test instruments, ventilation requirements and precautions when working with refrigeration systems and refrigerants.'),(75,9,3,'Learn Refrigerator Components and Operation','Understand the construction and operation of common refrigerator systems, including cooling circuits, temperature controls, fans, defrost systems, door seals and other commonly serviced components.'),(76,9,4,'Develop Testing and Fault-Diagnosis Skills','Learn systematic methods for identifying common refrigerator problems such as inadequate cooling, excessive frost, unusual noise, electrical faults, thermostat problems and airflow issues.'),(77,9,5,'Develop Refrigeration Servicing Skills','Learn appropriate procedures for cleaning, inspection, component testing, basic servicing and maintenance of refrigeration equipment under proper training and supervision.'),(78,9,6,'Learn Refrigerant-System Servicing','Develop an understanding of refrigerant circuits, leak detection, evacuation, charging and recovery procedures through appropriate technical training and safe practices. Refrigerant handling should only be performed by suitably trained persons using appropriate equipment and procedures.'),(79,9,7,'Complete Relevant Technical Training and Gain Practical Experience','Consider appropriate refrigeration and air-conditioning vocational training and gain supervised practical experience with an experienced refrigeration technician, appliance service centre or suitable workplace.'),(80,9,8,'Develop Advanced Diagnostic and Repair Skills','Progress into more complex troubleshooting involving compressors, control systems, defrost systems, sensors and other refrigerator components according to the technician’s training and competency.'),(81,9,9,'Start Independent Refrigerator Service Work','After gaining sufficient training and practical experience, provide suitable refrigerator maintenance and repair services, maintain service records, build a customer base and gradually develop an independent appliance-repair service.'),(82,10,1,'Learn Washing Machine Fundamentals','Understand the basic operation and major components of washing machines, including the drum, motor, pump, inlet valve, drain system, control system, door or lid mechanism and water-level system.'),(83,10,2,'Learn Electrical and Workplace Safety','Learn safe electrical isolation, use of PPE, safe handling of tools and test instruments, protection from water and electricity hazards, and safe practices while working on household appliances.'),(84,10,3,'Learn Installation and Basic Maintenance','Develop skills for appropriate installation, levelling, water inlet and drain connections, inspection, cleaning and routine maintenance according to the appliance manufacturer requirements.'),(85,10,4,'Develop Component Testing Skills','Learn how to inspect and test appropriate electrical and mechanical components such as motors, pumps, valves, switches, sensors and other serviceable parts using suitable diagnostic methods and equipment.'),(86,10,5,'Learn Fault Diagnosis','Develop a systematic approach to identifying common problems such as failure to start, water inlet problems, drainage issues, excessive vibration, unusual noise, spinning problems and control-related faults.'),(87,10,6,'Develop Repair and Replacement Skills','Learn appropriate procedures for repairing or replacing faulty components, reassembling appliances correctly and testing their operation after service work.'),(88,10,7,'Gain Technical Training and Supervised Experience','Consider suitable appliance-repair, electrical or related technical training and gain supervised practical experience with an appliance service centre, technician or repair business.'),(89,10,8,'Develop Advanced Diagnostic Skills','Progress toward more advanced troubleshooting involving electronic controls, sensors, motor systems and other appliance-specific technologies according to training and competency.'),(90,10,9,'Start Independent Appliance Repair Services','After gaining sufficient training and practical experience, provide suitable washing-machine maintenance and repair services, maintain service records, build customer trust and gradually establish an independent appliance-service business.'),(91,11,1,'Learn Welding Fundamentals and Safety','Understand welding principles, common welding equipment, welding terminology, metals and basic joint types. Learn PPE, fire prevention, ventilation, electrical safety and safe handling of welding equipment before beginning practical work.'),(92,11,2,'Develop Basic Welding Skills','Practice preparing metal surfaces, setting up welding equipment and producing basic welds under proper supervision. Develop control of heat, electrode or torch movement, travel speed and weld appearance.'),(93,11,3,'Learn Different Welding Processes','Develop practical knowledge of commonly used welding processes such as Shielded Metal Arc Welding (SMAW), Gas Metal Arc Welding (GMAW/MIG) and Gas Tungsten Arc Welding (GTAW/TIG), according to training and equipment availability.'),(94,11,4,'Learn Joint Preparation and Welding Positions','Learn preparation of different joint types and practise welding in appropriate positions. Develop the ability to select suitable welding parameters and consumables according to the material, process and application.'),(95,11,5,'Learn Fabrication and Drawing Skills','Develop skills in measuring, marking, cutting and fitting metal components. Learn to interpret basic engineering drawings and understand dimensions, symbols and welding-related information needed for fabrication work.'),(96,11,6,'Develop Weld Quality and Inspection Awareness','Learn to identify common welding defects such as porosity, cracks, undercut and incomplete fusion. Develop awareness of weld quality, visual inspection, dimensional accuracy and appropriate corrective practices.'),(97,11,7,'Complete Formal Welding Training and Gain Practical Experience','Consider an appropriate DGT vocational training pathway such as the Welder trade and gain supervised workplace experience in a fabrication workshop, manufacturing unit, construction environment or other suitable workplace.'),(98,11,8,'Develop Advanced Welding Specialization','After building a strong foundation, develop specialization in areas such as TIG welding, MIG/MAG welding, structural fabrication, pipe welding or another suitable industrial application according to training, qualifications and career goals.'),(99,11,9,'Build a Professional Welding Career or Business','Build a portfolio of suitable fabrication and welding work, gain industry experience, develop professional contacts and customer relationships, and progress toward skilled employment, contract work or an independent fabrication and welding service while following applicable safety and regulatory requirements.'),(100,12,1,'Learn Basic Laundry and Fabric Care','Understand common fabric types, basic garment-care symbols, colour separation, washing methods and the effects of water temperature, detergents and different cleaning processes on garments.'),(101,12,2,'Learn Safe Handling and Workplace Hygiene','Develop safe handling practices for detergents and cleaning products, proper ventilation, personal hygiene, equipment safety and appropriate procedures for handling customer garments.'),(102,12,3,'Develop Washing and Sorting Skills','Learn how to inspect, sort and prepare garments according to colour, fabric type, care instructions and cleaning requirements. Develop correct washing, rinsing and drying practices.'),(103,12,4,'Learn Stain Treatment and Garment Care','Learn to identify common stains and select appropriate treatment methods without unnecessarily damaging fabrics. Develop careful handling practices for delicate and specialty garments.'),(104,12,5,'Develop Professional Ironing and Finishing Skills','Learn safe use of irons, steam irons and suitable pressing equipment. Develop skills in temperature selection, wrinkle removal, garment shaping, folding and professional finishing.'),(105,12,6,'Learn Garment Inspection and Quality Control','Develop a systematic process for checking garments before and after service, identifying existing damage, ensuring correct cleaning and finishing, and preventing mix-ups or loss of customer items.'),(106,12,7,'Gain Practical Experience and Improve Service Skills','Work with an established laundry, ironing service or experienced professional to develop speed, consistency, garment handling, customer communication and order-management skills.'),(107,12,8,'Build Customer and Order Management Skills','Learn to record customer orders, identify garments correctly, calculate service charges, manage delivery or collection schedules, handle customer instructions and maintain reliable service records.'),(108,12,9,'Start an Independent Laundry or Ironing Service','After gaining sufficient practical experience, begin offering suitable laundry or ironing services independently, develop repeat customers, manage equipment and operating costs and gradually build a home-based, mobile or commercial service.'),(109,13,1,'Learn Basic Hairdressing Fundamentals','Understand hair types, basic hair structure, common hair-care products, salon tools and equipment, and fundamental hairdressing terminology.'),(110,13,2,'Learn Hygiene and Client Safety','Develop proper hand hygiene, tool cleaning and disinfection practices, workstation hygiene, safe handling of salon products and basic client consultation procedures.'),(111,13,3,'Develop Basic Hair Cutting Skills','Learn sectioning, combing and basic cutting techniques. Practise creating simple cuts while maintaining appropriate measurements, symmetry and client comfort.'),(112,13,4,'Develop Hair Washing and Treatment Skills','Learn proper hair washing, conditioning and basic treatment procedures. Understand how product selection and treatment techniques can vary according to hair type and client needs.'),(113,13,5,'Learn Hair Styling Techniques','Develop skills in blow-drying, straightening, curling, braiding and other suitable styling techniques. Practise creating neat everyday and occasion-based hairstyles.'),(114,13,6,'Develop Advanced Styling and Colouring Skills','Build skills in advanced haircuts, styling and suitable colouring techniques through proper training. Learn the importance of product selection, strand or patch testing where applicable and safe chemical handling.'),(115,13,7,'Gain Professional Training and Salon Experience','Consider relevant vocational or professional hairdressing training and gain supervised practical experience in a salon, beauty studio or suitable workplace.'),(116,13,8,'Build a Hair Styling Portfolio and Client Base','Document suitable completed hairstyles, improve consultation and communication skills, learn service pricing and appointment management, and develop a professional portfolio.'),(117,13,9,'Start Independent Hair Styling Services','After gaining sufficient practical experience, provide suitable independent hair services, develop repeat customers and consider a home-based salon, mobile service or commercial hair-styling business while following applicable local requirements.'),(118,14,1,'Learn Basic Nail Care Fundamentals','Understand nail structure, basic nail care, common nail conditions, manicure and pedicure tools, products and fundamental terminology used in professional nail services.'),(119,14,2,'Learn Hygiene, Sanitation and Client Safety','Learn proper hand hygiene, workstation sanitation, cleaning and appropriate disinfection of reusable tools, safe product handling and procedures for maintaining a hygienic nail-service environment.'),(120,14,3,'Develop Basic Manicure and Pedicure Skills','Learn nail shaping, filing, cuticle care, basic manicure and pedicure procedures, nail preparation and professional finishing while working carefully and comfortably with clients.'),(121,14,4,'Learn Basic Nail Art Techniques','Develop skills in colour application, simple designs, patterns, detailing, decorative elements and other basic nail-art techniques. Practise creating clean and consistent designs.'),(122,14,5,'Develop Gel and Other Nail Enhancement Skills','Through appropriate training, learn suitable techniques for gel polish and other nail enhancements, including correct preparation, application, curing and removal procedures.'),(123,14,6,'Develop Advanced Nail Art and Design Skills','Build advanced skills in detailed nail art, custom designs, occasion-based work and other suitable techniques. Continue practising precision, consistency and professional finishing.'),(124,14,7,'Gain Professional Training and Practical Experience','Consider appropriate beauty or nail-service training and gain supervised practical experience in a salon, nail studio or other suitable workplace.'),(125,14,8,'Build a Nail Art Portfolio and Client Base','Create a portfolio of suitable completed designs, improve client consultation and communication skills, learn service pricing and appointment management, and develop a professional online or offline portfolio.'),(126,14,9,'Start Independent Nail Services','After gaining sufficient training and practical experience, provide suitable independent nail-care and nail-art services, develop repeat customers and consider a home-based, mobile or commercial nail-service business while following applicable local requirements.'),(127,15,1,'Learn Photography Fundamentals','Understand camera types and basic camera controls such as aperture, shutter speed, ISO, focus, white balance, exposure and depth of field. Learn how these settings affect the final photograph.'),(128,15,2,'Learn Composition and Visual Storytelling','Develop an understanding of framing, perspective, rule of thirds, leading lines, balance, negative space and other composition principles. Practise creating photographs that communicate a clear subject or story.'),(129,15,3,'Develop Lighting Skills','Learn how natural and artificial light affect photographs. Practise controlling direction, intensity, shadows and exposure using available light and suitable lighting equipment.'),(130,15,4,'Develop Practical Shooting Skills','Practise photographing people, products, places and events in different environments. Learn to select appropriate camera settings, lenses, perspectives and shooting techniques for different situations.'),(131,15,5,'Learn Photo Editing and Post-Processing','Develop skills in organizing, selecting, cropping, colour correction, exposure adjustment, retouching and exporting photographs using appropriate editing software.'),(132,15,6,'Choose a Photography Specialization','Explore areas such as portrait photography, wedding and event photography, product photography, food photography, real-estate photography, fashion photography, travel photography or other suitable specializations.'),(133,15,7,'Gain Professional Experience and Build a Portfolio','Assist an experienced photographer or take suitable supervised projects to gain practical experience. Build a portfolio containing strong examples of the type of photography services you intend to provide.'),(134,15,8,'Develop Client and Business Skills','Learn client consultation, project planning, quotations, scheduling, contracts, image delivery, file organization and professional communication. Develop an understanding of equipment costs and basic business management.'),(135,15,9,'Start Independent Photography Services','After gaining sufficient technical and practical experience, take suitable photography assignments, build a professional reputation, develop repeat clients and gradually establish an independent photography service or studio.'),(136,16,1,'Learn Video Production Fundamentals','Understand basic video concepts such as frame rate, resolution, aspect ratio, shutter speed, exposure, focus, white balance and basic camera operation.'),(137,16,2,'Learn Composition and Visual Storytelling','Develop skills in framing, camera angles, shot sizes, movement, sequencing and visual storytelling. Practise planning shots that communicate a clear subject, event or story.'),(138,16,3,'Develop Camera and Shooting Skills','Practise recording interviews, events, products, people and locations using appropriate camera settings, lenses, tripods and other equipment. Learn to maintain stable and properly exposed footage.'),(139,16,4,'Learn Audio Recording for Video','Understand the importance of clean audio and learn to use suitable microphones and audio-recording equipment. Practise recording dialogue, ambient sound and other audio required for different productions.'),(140,16,5,'Develop Lighting and Production Skills','Learn how natural and artificial lighting can be used for video. Develop basic skills in planning locations, arranging lighting, preparing equipment and organizing a shoot.'),(141,16,6,'Learn Video Editing and Post-Production','Develop skills in organizing footage, cutting clips, arranging sequences, adding transitions where appropriate, synchronizing audio, basic colour correction, titles and exporting videos in suitable formats.'),(142,16,7,'Develop a Professional Video Portfolio','Create suitable sample projects such as event videos, promotional videos, interviews, short-form content or other productions. Build a portfolio that demonstrates shooting, audio and editing abilities.'),(143,16,8,'Gain Professional Experience and Client Skills','Work with an experienced videographer or production team where possible. Learn client consultation, project planning, quotations, scheduling, file management, delivery and professional communication.'),(144,16,9,'Start Independent Videography Services','After developing sufficient technical and practical experience, take suitable video assignments, build a professional reputation and client base, and gradually establish an independent videography service or production business.'),(145,17,1,'Learn Basic Audio Fundamentals','Understand basic concepts such as sound, frequency, volume, gain, signal flow, microphones, speakers, mixers, cables and common audio equipment.'),(146,17,2,'Learn Equipment Handling and Safety','Learn safe setup, connection and handling of mixers, amplifiers, speakers, microphones, controllers and cables. Develop electrical, equipment and venue safety practices and learn to protect audio equipment from damage.'),(147,17,3,'Develop Basic DJ Skills','Learn music organization, beat matching, tempo control, cueing, transitions and basic operation of DJ controllers or other suitable DJ equipment.'),(148,17,4,'Develop Mixing and Performance Skills','Practise smooth transitions, EQ use, effects, track selection and live performance techniques. Learn to adapt music selection and mixing style according to the type of event and audience.'),(149,17,5,'Learn Live Sound and PA Setup','Develop practical knowledge of microphones, speakers, mixers, amplifiers and signal routing. Learn how to set up, test and operate a basic PA system for suitable events.'),(150,17,6,'Develop Sound Troubleshooting Skills','Learn to identify and resolve common audio problems such as unwanted noise, feedback, incorrect gain levels, connection problems and microphone or speaker issues using safe troubleshooting methods.'),(151,17,7,'Gain Practical Event Experience','Assist an experienced DJ, sound technician or event production team to gain practical experience in equipment setup, sound checks, live operation, event coordination and equipment pack-down.'),(152,17,8,'Build a Professional Portfolio and Client Base','Record suitable performances or sound projects, develop an event portfolio, learn client consultation, quotations, scheduling and equipment planning, and build a reputation through reliable professional service.'),(153,17,9,'Start Independent DJ or Sound Services','After developing sufficient technical and practical experience, provide suitable DJ or sound services for events, develop repeat clients, manage equipment and operating costs, and gradually establish an independent DJ or sound-service business while following applicable venue and local requirements.');
