INSERT INTO `category_scheme_mapping` VALUES (1,1,1,'Useful for an eligible electrician who wants to establish a new electrical service business or workshop.',1),(2,1,2,'Useful for eligible micro-enterprise credit needs such as business equipment, tools or working capital.',2),(5,2,1,'Useful for an eligible plumber planning to establish a new plumbing service enterprise.',1),(6,2,2,'Useful for eligible business finance needs such as tools, equipment and working capital.',2),(9,3,1,'Useful for establishing an eligible new carpentry, furniture or woodworking micro-enterprise.',1),(10,3,2,'Useful for eligible finance needs related to tools, equipment and expansion of a carpentry business.',2),(11,3,3,'Carpenter is one of the specifically covered trades under PM Vishwakarma, subject to all scheme eligibility conditions.',3),(14,4,1,'Useful for an eligible painter planning to establish a new painting or decoration service enterprise.',1),(15,4,2,'Useful for eligible finance needs related to tools, equipment and working capital.',2),(18,5,1,'Useful for an eligible tailor planning to establish or expand a tailoring or garment-service micro-enterprise.',1),(19,5,2,'Useful for eligible finance needs such as sewing equipment, machinery and working capital.',2),(20,5,3,'Tailor is one of the specifically covered trades under PM Vishwakarma, subject to all scheme eligibility conditions.',3),(23,6,1,'Useful for an eligible beauty professional planning to establish a new salon or beauty-service micro-enterprise.',1),(24,6,2,'Useful for eligible finance needs such as beauty equipment, salon setup and working capital.',2),(27,7,1,'Useful for an eligible technician planning to establish an appliance repair or AC service micro-enterprise.',1),(28,7,2,'Useful for eligible finance needs such as diagnostic equipment, tools and working capital.',2),(31,8,1,'Useful for an eligible mechanic planning to establish a new automobile repair or service workshop.',1),(32,8,2,'Useful for eligible finance needs such as workshop equipment, tools and working capital.',2),(35,9,1,'Useful for an eligible technician planning to establish a refrigeration repair and service business.',1),(36,9,2,'Useful for eligible finance needs such as service tools, diagnostic equipment and working capital.',2),(39,10,1,'Useful for an eligible technician planning to establish an appliance repair and servicing enterprise.',1),(40,10,2,'Useful for eligible finance needs such as repair tools, testing equipment and working capital.',2),(43,11,1,'Useful for an eligible welder planning to establish a new fabrication or welding micro-enterprise.',1),(44,11,2,'Useful for eligible finance needs such as welding equipment, tools and working capital.',2),(47,12,1,'Useful for an eligible worker planning to establish a new laundry or garment-care micro-enterprise.',1),(48,12,2,'Useful for eligible finance needs such as laundry equipment, ironing equipment and working capital.',2),(49,12,3,'Potentially relevant where the worker is actually engaged in the eligible Washerman/Dhobi trade and satisfies PM Vishwakarma conditions.',3),(51,13,1,'Useful for an eligible hair stylist planning to establish a salon or hair-care service enterprise.',1),(52,13,2,'Useful for eligible finance needs such as salon equipment, tools and working capital.',2),(53,13,3,'Potentially relevant where the worker actually qualifies under the PM Vishwakarma Barber/Naai trade and satisfies all scheme conditions.',3),(55,14,1,'Useful for an eligible nail artist planning to establish a nail-care or beauty-service micro-enterprise.',1),(56,14,2,'Useful for eligible finance needs such as nail equipment, salon setup and working capital.',2),(58,15,1,'Useful for an eligible photographer planning to establish a photography studio or photography-service micro-enterprise.',1),(59,15,2,'Useful for eligible finance needs such as cameras, lighting equipment and other business requirements.',2),(61,16,1,'Useful for an eligible videographer planning to establish a video-production or media-service micro-enterprise.',1),(62,16,2,'Useful for eligible finance needs such as cameras, audio equipment, editing systems and working capital.',2),(64,17,1,'Useful for an eligible DJ or sound technician planning to establish a sound/event-service micro-enterprise.',1),(65,17,2,'Useful for eligible finance needs such as sound equipment, mixers, speakers and working capital.',2),(186,1,5,NULL,1),(187,2,5,NULL,1),(188,3,5,NULL,1),(189,4,5,NULL,1),(190,5,5,NULL,1),(191,6,5,NULL,1),(192,7,5,NULL,1),(193,8,5,NULL,1),(194,9,5,NULL,1),(195,10,5,NULL,1),(196,11,5,NULL,1),(197,17,5,NULL,1),(232,1,4,NULL,1),(233,2,4,NULL,1),(234,3,4,NULL,1),(235,4,4,NULL,1),(236,5,4,NULL,1),(237,6,4,NULL,1),(238,7,4,NULL,1),(239,8,4,NULL,1),(240,9,4,NULL,1),(241,10,4,NULL,1),(242,11,4,NULL,1),(243,12,4,NULL,1),(244,13,4,NULL,1),(245,14,4,NULL,1),(246,15,4,NULL,1),(247,16,4,NULL,1),(248,17,4,NULL,1),(257,1,7,NULL,1),(258,6,7,NULL,1);
