INSERT INTO `certifications` VALUES (1,1,'Electrician — Craftsmen Training Scheme (CTS)','Directorate General of Training (DGT), Ministry of Skill Development and Entrepreneurship','Government Vocational Qualification','Formal ITI trade training in electrical installation, wiring, electrical machines, testing, maintenance, safety and related electrical work. Successful trainees are awarded the National Trade Certificate (NTC).','Passed 10th class examination with Science and Mathematics, or with a vocational subject in the same sector, or equivalent.','2 years (2400 hours + OJT/Group Project)','https://dgt.gov.in/en/node/1110'),(2,1,'National Trade Certificate (NTC) — Electrician','Directorate General of Training (DGT)','National Trade Certificate','The NTC is awarded after successfully completing the relevant CTS trade and meeting the applicable assessment requirements. It provides a nationally recognized vocational qualification for the Electrician trade.','Successful completion of the DGT/NCVT Electrician CTS programme and applicable assessment requirements.','Linked to the 2-year Electrician CTS programme','https://dgt.gov.in/en/node/1110'),(3,1,'National Apprenticeship Certificate (NAC)','Directorate General of Training (DGT)','Apprenticeship Qualification','A formal apprenticeship pathway that allows an Electrician to gain structured industry experience and work-based training after or alongside the relevant vocational pathway, subject to applicable apprenticeship eligibility and rules.','Eligibility depends on the apprenticeship trade, establishment and applicable Apprenticeship Rules. ITI-qualified candidates can progress into apprenticeship opportunities.','Depends on the apprenticeship trade and programme','https://dgt.gov.in/'),(4,1,'Electrician – Power Distribution, CTS','Directorate General of Training (DGT), Ministry of Skill Development and Entrepreneurship','Government Vocational Qualification','A specialized DGT vocational trade focused on electrical power distribution work. It can be relevant to electricians seeking a career in power-distribution environments rather than general domestic electrical work.','Passed 10th class examination with Science and Mathematics or equivalent.','2 years (2400 hours)','https://dgt.gov.in/en/node/956'),(5,1,'Solar Technician (Electrical), CTS','Directorate General of Training (DGT)','Government Vocational Qualification','A related DGT trade covering electrical skills for solar-energy applications. It can be considered as an additional specialization for an electrician interested in solar electrical work.','Passed 10th class examination.','1 year (1200 hours)','https://dgt.gov.in/en/cts-details'),(6,2,'Plumber — Craftsmen Training Scheme (CTS)','Directorate General of Training (DGT), Ministry of Skill Development and Entrepreneurship','Government Vocational Qualification','Formal ITI vocational training in plumbing work, including pipe fitting, water supply systems, sanitary installations, drainage, maintenance, repair and safe working practices. Successful trainees are awarded the National Trade Certificate (NTC).','Passed 8th class examination.','1 year (1200 hours)','https://dgt.gov.in/en/node/1109'),(7,2,'National Trade Certificate (NTC) — Plumber','Directorate General of Training (DGT)','National Trade Certificate','The NTC is awarded after successful completion of the relevant CTS Plumber training and applicable All India Trade Test requirements. It is a recognized vocational qualification for relevant employment.','Successful completion of the DGT CTS Plumber programme and applicable assessment requirements.','Linked to the 1-year Plumber CTS programme','https://dgt.gov.in/en/node/1109'),(8,2,'National Apprenticeship Certificate (NAC) — Plumber','Directorate General of Training (DGT)','Apprenticeship Qualification','An apprenticeship pathway through which a qualified Plumber can gain structured workplace training and industry experience. The current DGT Plumber curriculum identifies apprenticeship as a progression pathway leading to the National Apprenticeship Certificate.','Eligibility depends on the applicable apprenticeship trade, establishment and Apprenticeship Rules. The DGT Plumber curriculum identifies NTC holders as eligible for relevant progression.','Depends on the applicable apprenticeship programme','https://dgt.gov.in/en/node/1109'),(9,2,'Craft Instructor Training Scheme (CITS) — Plumber','Directorate General of Training (DGT)','Instructor Training Qualification','Advanced instructor-training pathway for Plumber trade professionals who want to develop the skills required to become vocational instructors in ITIs, subject to the applicable CITS eligibility requirements.','The current DGT Plumber curriculum identifies CITS as a progression pathway. Specific eligibility depends on the applicable CITS admission rules.','As specified by the applicable CITS programme','https://dgt.gov.in/en/CTS'),(10,3,'Carpenter — Craftsmen Training Scheme (CTS)','Directorate General of Training (DGT), Ministry of Skill Development and Entrepreneurship','Government Vocational Qualification','Formal vocational training covering woodworking, measurement and marking, use of hand and power tools, joints, furniture work, wood finishing and practical carpentry skills. Successful trainees can receive the National Trade Certificate (NTC) after meeting the applicable assessment requirements.','Eligibility as specified by the current DGT CTS Carpenter trade admission requirements.','As specified by the current DGT CTS Carpenter programme','https://dgt.gov.in/en/cts-details'),(11,3,'National Trade Certificate (NTC) — Carpenter','Directorate General of Training (DGT)','National Trade Certificate','The NTC is the nationally recognized vocational qualification associated with successful completion of the relevant CTS Carpenter trade and applicable trade-test requirements.','Successful completion of the DGT CTS Carpenter programme and applicable assessment requirements.','Linked to the applicable CTS Carpenter programme','https://dgt.gov.in/en/cts-details'),(12,3,'National Apprenticeship Certificate (NAC) — Carpenter','Directorate General of Training (DGT)','Apprenticeship Qualification','An apprenticeship progression route that provides structured workplace training and practical industry experience in the Carpenter trade and can lead to the National Apprenticeship Certificate, subject to applicable apprenticeship rules and assessment.','Eligibility depends on the applicable apprenticeship trade, establishment and current Apprenticeship Rules.','Depends on the applicable apprenticeship programme','https://dgt.gov.in/'),(13,3,'Craft Instructor Training Scheme (CITS) — Carpenter','Directorate General of Training (DGT)','Instructor Training Qualification','An instructor-development pathway for eligible skilled Carpenter professionals who want to progress toward vocational teaching and instructor roles in the skill-training system.','Eligibility depends on the applicable DGT CITS admission requirements and Carpenter trade qualification.','As specified by the applicable CITS programme','https://dgt.gov.in/en/CTS'),(14,4,'Painter (General) — Craftsmen Training Scheme (CTS)','Directorate General of Training (DGT), Ministry of Skill Development and Entrepreneurship','Government Vocational Qualification','Formal vocational training covering surface preparation, preparation and application of paints, primers and finishes, colour work, brush and spray techniques, and safe painting practices for professional work.','Eligibility as specified by the current DGT CTS Painter (General) trade admission requirements.','As specified by the current DGT CTS Painter (General) programme','https://dgt.gov.in/en/cts-details'),(15,4,'National Trade Certificate (NTC) — Painter (General)','Directorate General of Training (DGT)','National Trade Certificate','A nationally recognized vocational qualification awarded after successful completion of the relevant CTS Painter (General) trade and applicable trade-test requirements.','Successful completion of the DGT CTS Painter (General) programme and applicable assessment requirements.','Linked to the applicable CTS Painter (General) programme','https://dgt.gov.in/en/cts-details'),(16,4,'National Apprenticeship Certificate (NAC) — Painter','Directorate General of Training (DGT)','Apprenticeship Qualification','An apprenticeship progression route that provides structured workplace training and practical experience in painting-related work and can lead to the National Apprenticeship Certificate, subject to the applicable apprenticeship trade and assessment requirements.','Eligibility depends on the applicable apprenticeship trade, establishment and current Apprenticeship Rules.','Depends on the applicable apprenticeship programme','https://dgt.gov.in/'),(17,4,'Craft Instructor Training Scheme (CITS) — Painter','Directorate General of Training (DGT)','Instructor Training Qualification','An instructor-development pathway for eligible skilled professionals who want to progress toward vocational teaching and instructor roles within the skill-training system.','Eligibility depends on the applicable DGT CITS admission requirements and relevant trade qualification.','As specified by the applicable CITS programme','https://dgt.gov.in/en/CTS'),(18,5,'Tailor — Craftsmen Training Scheme (CTS)','Directorate General of Training (DGT), Ministry of Skill Development and Entrepreneurship','Government Vocational Qualification','Formal vocational training covering garment measurement, cutting, sewing, machine operation, garment construction, finishing and basic tailoring techniques for professional work.','Eligibility as specified by the current DGT CTS Tailor trade admission requirements.','As specified by the current DGT CTS Tailor programme','https://dgt.gov.in/en/cts-details'),(19,5,'National Trade Certificate (NTC) — Tailor','Directorate General of Training (DGT)','National Trade Certificate','A nationally recognized vocational qualification awarded after successful completion of the relevant CTS Tailor trade and applicable trade-test requirements.','Successful completion of the DGT CTS Tailor programme and applicable assessment requirements.','Linked to the applicable CTS Tailor programme','https://dgt.gov.in/en/cts-details'),(20,5,'National Apprenticeship Certificate (NAC) — Tailor','Directorate General of Training (DGT)','Apprenticeship Qualification','An apprenticeship progression route that provides structured workplace training and practical experience in tailoring or garment-related work and can lead to the National Apprenticeship Certificate, subject to the applicable apprenticeship trade and assessment requirements.','Eligibility depends on the applicable apprenticeship trade, establishment and current Apprenticeship Rules.','Depends on the applicable apprenticeship programme','https://dgt.gov.in/'),(21,5,'Craft Instructor Training Scheme (CITS) — Tailoring','Directorate General of Training (DGT)','Instructor Training Qualification','An instructor-development pathway for eligible skilled tailoring professionals who want to progress toward vocational teaching and instructor roles within the skill-training system.','Eligibility depends on the applicable DGT CITS admission requirements and relevant trade qualification.','As specified by the applicable CITS programme','https://dgt.gov.in/en/CTS'),(22,6,'Beauty Therapist — Craftsmen Training Scheme (CTS)','Directorate General of Training (DGT), Ministry of Skill Development and Entrepreneurship','Government Vocational Qualification','Formal vocational training covering beauty therapy, skin care, basic hair care, manicure and pedicure, make-up, client care, hygiene and professional beauty-service practices.','Eligibility as specified by the current DGT CTS Beauty Therapist trade admission requirements.','As specified by the current DGT CTS Beauty Therapist programme','https://dgt.gov.in/en/cts-details'),(23,6,'National Trade Certificate (NTC) — Beauty Therapist','Directorate General of Training (DGT)','National Trade Certificate','A nationally recognized vocational qualification associated with successful completion of the relevant CTS Beauty Therapist trade and applicable trade-test requirements.','Successful completion of the DGT CTS Beauty Therapist programme and applicable assessment requirements.','Linked to the applicable CTS Beauty Therapist programme','https://dgt.gov.in/en/cts-details'),(24,6,'National Apprenticeship Certificate (NAC) — Beauty & Wellness Related Trade','Directorate General of Training (DGT)','Apprenticeship Qualification','An apprenticeship pathway through which eligible candidates can gain structured workplace training and practical experience in an applicable beauty and wellness occupation, subject to the available apprenticeship trade and current rules.','Depends on the applicable apprenticeship trade, establishment and current Apprenticeship Rules.','Depends on the applicable apprenticeship programme','https://dgt.gov.in/'),(25,6,'Craft Instructor Training Scheme (CITS) — Beauty & Wellness Related Trade','Directorate General of Training (DGT)','Instructor Training Qualification','An instructor-development pathway for eligible skilled professionals who want to progress toward vocational teaching and instructor roles, subject to the applicable CITS trade and admission requirements.','Eligibility depends on the applicable DGT CITS admission requirements and relevant vocational qualification.','As specified by the applicable CITS programme','https://dgt.gov.in/en/CTS'),(26,7,'Refrigeration and Air Conditioning Technician — Craftsmen Training Scheme (CTS)','Directorate General of Training (DGT), Ministry of Skill Development and Entrepreneurship','Government Vocational Qualification','Formal vocational training covering refrigeration and air-conditioning systems, installation, servicing, maintenance, electrical and mechanical components, refrigerants, fault diagnosis and safe working practices.','Eligibility as specified by the current DGT CTS Refrigeration and Air Conditioning Technician trade admission requirements.','As specified by the current DGT CTS programme','https://dgt.gov.in/en/cts-details'),(27,7,'National Trade Certificate (NTC) — Refrigeration and Air Conditioning Technician','Directorate General of Training (DGT)','National Trade Certificate','A nationally recognized vocational qualification associated with successful completion of the relevant CTS Refrigeration and Air Conditioning Technician trade and applicable trade-test requirements.','Successful completion of the DGT CTS Refrigeration and Air Conditioning Technician programme and applicable assessment requirements.','Linked to the applicable CTS programme','https://dgt.gov.in/en/cts-details'),(28,7,'National Apprenticeship Certificate (NAC) — Refrigeration and Air Conditioning Related Trade','Directorate General of Training (DGT)','Apprenticeship Qualification','An apprenticeship pathway that allows eligible candidates to gain structured workplace training and practical experience in an applicable refrigeration, air-conditioning or related technical occupation, subject to the available apprenticeship trade and current rules.','Depends on the applicable apprenticeship trade, establishment and current Apprenticeship Rules.','Depends on the applicable apprenticeship programme','https://dgt.gov.in/'),(29,7,'Craft Instructor Training Scheme (CITS) — Refrigeration and Air Conditioning Related Trade','Directorate General of Training (DGT)','Instructor Training Qualification','An instructor-development pathway for eligible technical professionals who want to progress toward vocational teaching and instructor roles in the skill-training system.','Eligibility depends on the applicable DGT CITS admission requirements and relevant trade qualification.','As specified by the applicable CITS programme','https://dgt.gov.in/en/CTS'),(30,8,'Mechanic Motor Vehicle — Craftsmen Training Scheme (CTS)','Directorate General of Training (DGT), Ministry of Skill Development and Entrepreneurship','Government Vocational Qualification','Formal vocational training covering automobile systems, engines, transmission, electrical systems, fuel and emission systems, vehicle servicing, diagnostics, repair and workshop safety.','Eligibility as specified by the current DGT CTS Mechanic Motor Vehicle trade admission requirements.','As specified by the current DGT CTS programme','https://dgt.gov.in/en/cts-details'),(31,8,'National Trade Certificate (NTC) — Mechanic Motor Vehicle','Directorate General of Training (DGT)','National Trade Certificate','A nationally recognized vocational qualification associated with successful completion of the relevant CTS Mechanic Motor Vehicle trade and applicable trade-test requirements.','Successful completion of the DGT CTS Mechanic Motor Vehicle programme and applicable assessment requirements.','Linked to the applicable CTS programme','https://dgt.gov.in/en/cts-details'),(32,8,'National Apprenticeship Certificate (NAC) — Motor Vehicle Related Trade','Directorate General of Training (DGT)','Apprenticeship Qualification','An apprenticeship pathway that provides structured workplace training and practical experience in an applicable motor-vehicle trade and can lead to the National Apprenticeship Certificate, subject to the applicable apprenticeship trade and assessment requirements.','Eligibility depends on the applicable apprenticeship trade, establishment and current Apprenticeship Rules.','Depends on the applicable apprenticeship programme','https://dgt.gov.in/'),(33,8,'Craft Instructor Training Scheme (CITS) — Mechanic Motor Vehicle','Directorate General of Training (DGT)','Instructor Training Qualification','An instructor-development pathway for eligible motor-vehicle professionals who want to progress toward vocational teaching and instructor roles within the skill-training system.','Eligibility depends on the applicable DGT CITS admission requirements and relevant trade qualification.','As specified by the applicable CITS programme','https://dgt.gov.in/en/CTS'),(34,9,'Refrigeration and Air Conditioning Technician — Craftsmen Training Scheme (CTS)','Directorate General of Training (DGT), Ministry of Skill Development and Entrepreneurship','Government Vocational Qualification','Formal vocational training covering refrigeration systems, domestic and commercial refrigeration equipment, compressors, condensers, evaporators, refrigerant circuits, electrical components, servicing, fault diagnosis and safe maintenance practices.','Eligibility as specified by the current DGT CTS Refrigeration and Air Conditioning Technician trade admission requirements.','As specified by the current DGT CTS programme','https://dgt.gov.in/en/cts-details'),(35,9,'National Trade Certificate (NTC) — Refrigeration and Air Conditioning Technician','Directorate General of Training (DGT)','National Trade Certificate','A nationally recognized vocational qualification associated with successful completion of the relevant CTS Refrigeration and Air Conditioning Technician trade and applicable trade-test requirements. The training provides a foundation for work involving refrigeration equipment, including relevant domestic and commercial applications.','Successful completion of the DGT CTS Refrigeration and Air Conditioning Technician programme and applicable assessment requirements.','Linked to the applicable CTS programme','https://dgt.gov.in/en/cts-details'),(36,9,'National Apprenticeship Certificate (NAC) — Refrigeration and Air Conditioning Related Trade','Directorate General of Training (DGT)','Apprenticeship Qualification','An apprenticeship pathway that provides structured workplace training and practical experience in an applicable refrigeration and air-conditioning occupation and can lead to the National Apprenticeship Certificate, subject to the available apprenticeship trade and assessment requirements.','Eligibility depends on the applicable apprenticeship trade, establishment and current Apprenticeship Rules.','Depends on the applicable apprenticeship programme','https://dgt.gov.in/'),(37,9,'Craft Instructor Training Scheme (CITS) — Refrigeration and Air Conditioning Related Trade','Directorate General of Training (DGT)','Instructor Training Qualification','An instructor-development pathway for eligible refrigeration and air-conditioning professionals who want to progress toward vocational teaching and instructor roles in the skill-training system.','Eligibility depends on the applicable DGT CITS admission requirements and relevant trade qualification.','As specified by the applicable CITS programme','https://dgt.gov.in/en/CTS'),(38,10,'Refrigeration and Air Conditioning Technician — Craftsmen Training Scheme (CTS)','Directorate General of Training (DGT), Ministry of Skill Development and Entrepreneurship','Government Vocational Qualification','Formal vocational training covering electrical and mechanical components, appliance servicing, refrigeration and air-conditioning systems, installation, maintenance, testing and fault diagnosis. These skills provide a relevant technical foundation for appliance-service work.','Eligibility as specified by the current DGT CTS Refrigeration and Air Conditioning Technician trade admission requirements.','As specified by the current DGT CTS programme','https://dgt.gov.in/en/cts-details'),(39,10,'National Trade Certificate (NTC) — Refrigeration and Air Conditioning Technician','Directorate General of Training (DGT)','National Trade Certificate','A nationally recognized vocational qualification associated with successful completion of the relevant CTS trade and applicable trade-test requirements. The technical skills can support progression into appliance servicing and related technical occupations.','Successful completion of the DGT CTS Refrigeration and Air Conditioning Technician programme and applicable assessment requirements.','Linked to the applicable CTS programme','https://dgt.gov.in/en/cts-details'),(40,10,'National Apprenticeship Certificate (NAC) — Appliance / Related Technical Trade','Directorate General of Training (DGT)','Apprenticeship Qualification','An apprenticeship route through which eligible candidates can gain structured workplace training and practical experience in an applicable technical trade. The exact apprenticeship occupation depends on available trades and establishments.','Eligibility depends on the applicable apprenticeship trade, establishment and current Apprenticeship Rules.','Depends on the applicable apprenticeship programme','https://dgt.gov.in/'),(41,10,'Craft Instructor Training Scheme (CITS) — Related Technical Trade','Directorate General of Training (DGT)','Instructor Training Qualification','An instructor-development pathway for eligible technical professionals who want to progress toward vocational teaching and instructor roles. The exact CITS trade depends on the professional qualification and current DGT offerings.','Eligibility depends on the applicable DGT CITS admission requirements and relevant trade qualification.','As specified by the applicable CITS programme','https://dgt.gov.in/en/CTS'),(42,11,'Welder — Craftsmen Training Scheme (CTS)','Directorate General of Training (DGT), Ministry of Skill Development and Entrepreneurship','Government Vocational Qualification','Formal vocational training covering welding fundamentals, welding equipment, metal preparation, different welding techniques, joints, welding positions, fabrication practices, defect identification and workplace safety.','Eligibility as specified by the current DGT CTS Welder trade admission requirements.','As specified by the current DGT CTS Welder programme','https://dgt.gov.in/en/cts-details'),(43,11,'National Trade Certificate (NTC) — Welder','Directorate General of Training (DGT)','National Trade Certificate','A nationally recognized vocational qualification associated with successful completion of the relevant CTS Welder trade and applicable trade-test requirements.','Successful completion of the DGT CTS Welder programme and applicable assessment requirements.','Linked to the applicable CTS Welder programme','https://dgt.gov.in/en/cts-details'),(44,11,'National Apprenticeship Certificate (NAC) — Welder','Directorate General of Training (DGT)','Apprenticeship Qualification','An apprenticeship pathway providing structured workplace training and practical industrial experience in an applicable welding trade. Successful completion can lead to the National Apprenticeship Certificate subject to applicable rules and assessment.','Eligibility depends on the applicable apprenticeship trade, establishment and current Apprenticeship Rules.','Depends on the applicable apprenticeship programme','https://dgt.gov.in/'),(45,11,'Craft Instructor Training Scheme (CITS) — Welder','Directorate General of Training (DGT)','Instructor Training Qualification','An instructor-development pathway for eligible welding professionals who want to progress toward vocational teaching and instructor roles within the skill-training system.','Eligibility depends on the applicable DGT CITS admission requirements and relevant Welder trade qualification.','As specified by the applicable CITS programme','https://dgt.gov.in/en/CTS'),(46,12,'Laundry Services — Skill Training / Vocational Qualification','National Skill Development Corporation (NSDC) / Sector Skill Council ecosystem','Skill Qualification','Relevant vocational training for laundry-service workers covering fabric identification, washing methods, stain treatment, drying, ironing, finishing, customer handling, workplace hygiene and safe use of equipment.','Eligibility depends on the specific qualification and training programme offered by an approved training provider.','Depends on the applicable qualification programme','https://www.nsdcindia.org/'),(47,12,'Apparel / Textile Related Skill Qualification','Apparel Made-Ups and Home Furnishing Sector Skill Council (AMHSSC)','Sector Skill Qualification','Skill-development pathways in the apparel and textile sector that can provide relevant knowledge in garment handling, finishing, quality practices and textile-related work useful for workers offering laundry, ironing or garment-care services.','Eligibility depends on the specific qualification pack and training programme.','Depends on the applicable qualification','https://www.amhssc.com/'),(48,12,'Recognition of Prior Learning (RPL)','National Skill Development Corporation (NSDC) / Skill India','Recognition / Skill Certification','Recognition of existing occupational skills for workers who already have practical experience but may not possess a formal qualification. RPL can assess existing skills against an applicable qualification standard where an appropriate programme is available.','Existing work experience and eligibility under the applicable RPL programme.','Depends on the applicable RPL programme','https://www.skillindiadigital.gov.in/'),(49,12,'National Apprenticeship / Work-Based Skill Development','Directorate General of Training (DGT)','Apprenticeship / Work-Based Training','Work-based training can provide practical occupational experience where a suitable apprenticeship trade or establishment is available. The exact occupation and eligibility depend on the current apprenticeship framework.','Depends on the applicable apprenticeship trade, establishment and current rules.','Depends on the applicable programme','https://dgt.gov.in/'),(50,13,'Hair & Skin Care — Craftsmen Training Scheme (CTS)','Directorate General of Training (DGT), Ministry of Skill Development and Entrepreneurship','Government Vocational Qualification','Formal vocational training covering hair care, hair cutting, styling, shampooing, hair treatments, skin care, hygiene, salon practices, client handling and related beauty-service skills.','Eligibility as specified by the current DGT CTS Hair & Skin Care trade admission requirements.','As specified by the current DGT CTS programme','https://dgt.gov.in/en/cts-details'),(51,13,'National Trade Certificate (NTC) — Hair & Skin Care','Directorate General of Training (DGT)','National Trade Certificate','A nationally recognized vocational qualification associated with successful completion of the relevant CTS Hair & Skin Care trade and applicable trade-test requirements.','Successful completion of the DGT CTS Hair & Skin Care programme and applicable assessment requirements.','Linked to the applicable CTS programme','https://dgt.gov.in/en/cts-details'),(52,13,'Recognition of Prior Learning (RPL) — Hair & Beauty Occupations','National Skill Development Corporation (NSDC) / Skill India','Recognition / Skill Certification','A pathway for experienced hair and beauty workers who have developed practical skills through work but do not hold a formal qualification. Where an applicable qualification is available, existing skills can be assessed against the relevant occupational standard.','Existing occupational experience and eligibility under the applicable RPL programme.','Depends on the applicable RPL programme','https://www.skillindiadigital.gov.in/'),(53,13,'Craft Instructor Training Scheme (CITS) — Hair & Beauty Related Trade','Directorate General of Training (DGT)','Instructor Training Qualification','An instructor-development pathway for eligible skilled professionals who want to progress toward vocational teaching and instructor roles in the skill-training system.','Eligibility depends on the applicable DGT CITS admission requirements and relevant vocational qualification.','As specified by the applicable CITS programme','https://dgt.gov.in/en/CTS'),(54,14,'Nail Technician — Qualification Pack BWS/Q0403','Beauty & Wellness Sector Skill Council (B&WSSC) / NCVET / Skill India ecosystem','NSQF Skill Qualification','Recognized occupational qualification covering professional nail-care services including manicure and pedicure, acrylic nail enhancement and overlays, UV gel enhancements, refilling, gel polish, electric filing, nail art and workplace health and safety.','Minimum education/experience requirements are specified in the current BWS/Q0403 qualification pack.','420 notional hours','https://www.bwssc.in/qualifications-packs/'),(55,14,'Assistant Nail Technician — Qualification Pack BWS/Q0401','Beauty & Wellness Sector Skill Council (B&WSSC) / NCVET / Skill India ecosystem','NSQF Skill Qualification','Entry-level professional qualification covering preparation and maintenance of the nail-care work area, manicure and pedicure, basic nail enhancements, refilling, basic nail art and workplace health and safety.','Eligibility as specified by the current BWS/Q0401 qualification pack.','330 notional hours','https://www.bwssc.in/qualifications-packs/'),(56,14,'Pedicurist and Manicurist — Qualification Pack BWS/Q0402','Beauty & Wellness Sector Skill Council (B&WSSC) / NCVET / Skill India ecosystem','NSQF Skill Qualification','Recognized skill qualification focused on professional manicure and pedicure services, nail care, client preparation, hygiene, safety and related beauty-service practices.','Eligibility as specified by the current BWS/Q0402 qualification pack.','420 notional hours','https://www.bwssc.in/qualifications-packs/'),(57,14,'Recognition of Prior Learning (RPL) — Nail Care Occupations','National Skill Development Corporation (NSDC) / Skill India','Recognition / Skill Certification','A pathway for experienced nail-care workers who have acquired practical skills through employment or self-employment but do not hold a formal qualification. Where an applicable qualification is available, existing skills can be assessed against the relevant occupational standard.','Existing occupational experience and eligibility under the applicable RPL programme.','Depends on the applicable RPL programme','https://www.skillindiadigital.gov.in/'),(58,15,'Photographer — Qualification Pack','Media & Entertainment Skills Council (MESC) / NCVET / Skill India ecosystem','NSQF Skill Qualification','Occupational skill qualification covering professional photography practices, camera operation, composition, lighting, image capture, equipment handling, workflow and professional work practices.','Eligibility depends on the current MESC qualification pack and applicable training requirements.','As specified by the applicable qualification pack','https://mescindia.org/'),(59,15,'Assistant Photographer — Qualification Pack','Media & Entertainment Skills Council (MESC) / NCVET / Skill India ecosystem','NSQF Skill Qualification','Entry-level pathway covering camera and photography equipment assistance, preparation of shoots, lighting support, image capture support and professional photography workflow.','Eligibility depends on the current MESC qualification pack and applicable training requirements.','As specified by the applicable qualification pack','https://mescindia.org/'),(60,15,'Recognition of Prior Learning (RPL) — Photography Occupations','National Skill Development Corporation (NSDC) / Skill India','Recognition / Skill Certification','A pathway for experienced photographers who developed their skills through employment, freelance work or self-employment but do not hold a formal qualification. Where an applicable qualification is available, existing skills can be assessed against the relevant occupational standard.','Existing occupational experience and eligibility under the applicable RPL programme.','Depends on the applicable RPL programme','https://www.skillindiadigital.gov.in/'),(61,15,'National Apprenticeship / Work-Based Training — Media & Entertainment Sector','Directorate General of Training (DGT) / applicable sector ecosystem','Apprenticeship / Work-Based Training','Where an applicable apprenticeship occupation and establishment are available, structured workplace training can provide practical experience in photography, media production or a related occupation.','Depends on the applicable apprenticeship occupation, establishment and current rules.','Depends on the applicable programme','https://dgt.gov.in/'),(62,16,'Video Editor — Qualification Pack','Media & Entertainment Skills Council (MESC) / NCVET / Skill India ecosystem','NSQF Skill Qualification','Occupational skill qualification covering professional video editing, editing workflow, media management, audio and video synchronization, transitions, effects, output formats and professional post-production practices.','Eligibility depends on the current MESC qualification pack and applicable training requirements.','As specified by the applicable qualification pack','https://mescindia.org/'),(63,16,'Assistant Video Editor — Qualification Pack','Media & Entertainment Skills Council (MESC) / NCVET / Skill India ecosystem','NSQF Skill Qualification','Entry-level pathway covering preparation of video editing projects, media organization, basic editing operations, file management and assistance in professional post-production workflows.','Eligibility depends on the current MESC qualification pack and applicable training requirements.','As specified by the applicable qualification pack','https://mescindia.org/'),(64,16,'Recognition of Prior Learning (RPL) — Media & Entertainment Occupations','National Skill Development Corporation (NSDC) / Skill India','Recognition / Skill Certification','A pathway for experienced videographers and media workers who have developed practical skills through employment, freelance work or self-employment but do not hold a formal qualification. Where an applicable qualification is available, existing skills can be assessed against the relevant occupational standard.','Existing occupational experience and eligibility under the applicable RPL programme.','Depends on the applicable RPL programme','https://www.skillindiadigital.gov.in/'),(65,16,'National Apprenticeship / Work-Based Training — Media & Entertainment Sector','Directorate General of Training (DGT) / applicable sector ecosystem','Apprenticeship / Work-Based Training','Where an applicable apprenticeship occupation and establishment are available, structured workplace training can provide practical experience in video production, editing, media production or a related occupation.','Depends on the applicable apprenticeship occupation, establishment and current rules.','Depends on the applicable programme','https://dgt.gov.in/'),(66,17,'Sound Assistant — Qualification Pack MES/Q3403','Media & Entertainment Skills Council (MESC) / NCVET / Skill India ecosystem','NSQF Skill Qualification','Entry-level sound qualification covering preparation and handling of sound equipment, sound-system setup, microphone and cable handling, basic sound checks, equipment maintenance and assistance during productions and events.','Eligibility depends on the current MES/Q3403 qualification pack and applicable training requirements.','390 notional hours','https://www.mescindia.org/qualification-packs'),(67,17,'Sound Engineer — Qualification Pack MES/Q3402','Media & Entertainment Skills Council (MESC) / NCVET / Skill India ecosystem','NSQF Skill Qualification','Professional sound qualification covering sound recording and production workflows, sound equipment operation, sound-system setup, technical sound requirements and professional audio practices.','Eligibility depends on the current MES/Q3402 qualification pack and applicable training requirements.','420 notional hours','https://www.mescindia.org/qualification-packs'),(68,17,'Sound Designer — Qualification Pack MES/Q3401','Media & Entertainment Skills Council (MESC) / NCVET / Skill India ecosystem','NSQF Skill Qualification','Advanced sound pathway covering sound design, audio creation and manipulation, sound effects, creative audio decisions and professional sound-production workflows.','Eligibility depends on the current MES/Q3401 qualification pack and applicable training requirements.','540 notional hours','https://www.mescindia.org/qualification-packs'),(69,17,'Sound Editor — Qualification Pack MES/Q3404','Media & Entertainment Skills Council (MESC) / NCVET / Skill India ecosystem','NSQF Skill Qualification','Professional audio post-production pathway covering sound editing, synchronization, audio cleanup, editing workflows and preparation of sound for media productions.','Eligibility depends on the current MES/Q3404 qualification pack and applicable training requirements.','510 notional hours','https://www.mescindia.org/qualification-packs');
