INSERT INTO `government_schemes` VALUES (1,'Prime Minister Employment Generation Programme (PMEGP)','Ministry of Micro, Small and Medium Enterprises','Credit-linked subsidy / self-employment','PMEGP supports eligible individuals in establishing new micro-enterprises in the non-farm sector. It is particularly useful for skilled workers who want to move from individual work into their own service business, workshop, studio or other eligible micro-enterprise.','Generally available to individuals above 18 years for eligible new projects. There is no income ceiling for assistance for new enterprises. Additional educational requirements apply for projects above specified project-cost thresholds. Existing units and projects that have already received certain government subsidies are subject to scheme restrictions.','Credit-linked margin-money subsidy for eligible new micro-enterprises, subject to the applicable project category, location, beneficiary category, project cost and scheme guidelines.','Applications are processed through the PMEGP/KVIC system and implementing agencies including KVIC, KVIBs, District Industries Centres and participating banks.','https://pmegp.msme.gov.in/','Active','2026-08-23'),(2,'Pradhan Mantri Mudra Yojana (PMMY)','Ministry of Finance','Micro-enterprise credit','PMMY provides institutional credit support for eligible micro-enterprise activities. It can be relevant to skilled workers who need finance for business activities, equipment or eligible working-capital requirements.','Eligibility depends on the proposed business activity, borrower status, lender requirements and current PMMY rules. Eligible activities include certain service-sector businesses, traders and shopkeepers, equipment finance for micro units and specified commercial transport activities.','Business loans and eligible credit facilities through participating financial institutions, subject to lender assessment and scheme conditions.','Applications are made through eligible banks, NBFCs, MFIs and other participating lending institutions.','https://www.myscheme.gov.in/schemes/pradhan-mantri-mudra-yojana','Active','2026-08-23'),(3,'PM Vishwakarma','Ministry of Micro, Small and Medium Enterprises','Artisan support / skill development / credit','PM Vishwakarma supports eligible traditional artisans and craftspeople working with their hands and tools in specified trades. It combines recognition, skill development, toolkit support, credit support and other assistance.','Available only to eligible artisans and craftspeople working in the trades covered by the scheme and meeting the scheme conditions. The occupation must match one of the specified trades.','Recognition through certificate and ID card, skill verification and training, toolkit incentive, credit support, digital transaction incentives and marketing support, subject to applicable scheme conditions.','Eligible beneficiaries can apply through the prescribed PM Vishwakarma registration and verification process, including Common Service Centres and the official scheme portal.','https://pmvishwakarma.gov.in/','Active','2026-08-23'),(4,'Pradhan Mantri Kaushal Vikas Yojana (PMKVY)','Ministry of Skill Development and Entrepreneurship','Skill training/ certification','PMKVY provides access to skill-development opportunities through approved job roles and training pathways. It can help workers acquire new skills, improve existing skills or obtain recognition of skills depending on the applicable component and available programme.','Eligibility varies according to the applicable PMKVY component, qualification/job role, training centre and current programme rules. Candidates should check currently available courses and eligibility through the official Skill India Digital system.','Skill training and assessment/certification opportunities under applicable programme components. Benefits depend on the selected job role and programme.','Candidates can search and enrol through the Skill India Digital ecosystem or applicable authorised training channels.','https://www.skillindiadigital.gov.in/','Active','2026-08-23'),(5,'National Apprenticeship Promotion Scheme (NAPS)','Ministry of Skill Development and Entrepreneurship / Directorate General of Training','Apprenticeship/ work-based training','NAPS promotes apprenticeship training by supporting employers and encouraging candidates to gain structured workplace experience. It can be useful for workers who want practical industry exposure and a pathway into formal employment.','Eligibility depends on the applicable apprenticeship trade, qualification requirements, establishment and current apprenticeship rules.','Structured on-the-job training and apprenticeship experience. Government support to employers is provided according to the applicable scheme provisions.','Candidates can search for applicable apprenticeship opportunities through the official apprenticeship ecosystem.','https://www.apprenticeshipindia.gov.in/','Active','2026-08-23'),(7,'pmk','','Skill training/ certification','','','','','','Active',NULL);
/*!40000 ALTER TABLE `government_schemes` ENABLE KEYS */;
UNLOCK TABLES;

