--
-- Table structure for table `main_government_schemes`
--

DROP TABLE IF EXISTS `main_government_schemes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `main_government_schemes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `scheme_name` varchar(255) NOT NULL,
  `department` varchar(255) DEFAULT NULL,
  `scheme_category` varchar(100) NOT NULL DEFAULT 'General',
  `category` varchar(100) NOT NULL,
  `state` varchar(100) NOT NULL,
  `gender` varchar(50) NOT NULL,
  `occupation` varchar(100) NOT NULL,
  `age_group` varchar(100) NOT NULL,
  `income_range` varchar(100) NOT NULL,
  `description` text,
  `eligibility` text,
  `benefits` text,
  `documents` text,
  `application_method` text,
  `official_link` varchar(500) DEFAULT NULL,
  `deadline` date DEFAULT NULL,
  `status` varchar(50) DEFAULT 'Active',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

