/*!40000 ALTER TABLE `main_government_schemes` DISABLE KEYS */;
INSERT INTO `main_government_schemes` VALUES (1,'PM-KISAN Samman Nidhi','Ministry of Agriculture & Farmers Welfare','Farmer','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Farmer','18-21,21-35,35-60,60+','All','Income support scheme for eligible landholding farmer families.','Eligible landholding farmer families subject to applicable PM-KISAN eligibility and exclusion criteria.','₹6,000 per year in three equal installments through DBT.','Aadhaar, bank account details, land records and other required documents.','Register through the PM-KISAN portal and the prescribed state process.','https://pmkisan.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(2,'Kisan Credit Card (KCC)','Ministry of Agriculture & Farmers Welfare','Farmer','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Farmer','18-21,21-35,35-60,60+','All','Credit facility for farmers for agricultural and eligible allied activities.','Farmers and other eligible agricultural beneficiaries subject to bank and scheme conditions.','Agricultural working-capital and investment credit.','Identity proof, address proof, land records and other bank-required documents.','Apply through a participating bank.','https://www.myscheme.gov.in/schemes/kcc',NULL,'Active','2026-09-03 13:36:21'),(3,'Pradhan Mantri Fasal Bima Yojana (PMFBY)','Ministry of Agriculture & Farmers Welfare','Farmer','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Farmer','18-21,21-35,35-60,60+','All','Crop insurance scheme protecting eligible farmers against specified crop losses.','Farmers with eligible notified crops and areas under the applicable scheme rules.','Crop insurance coverage and claim support.','Aadhaar or identity proof, bank details, land or cultivation records and crop details.','Apply through the PMFBY portal, bank, CSC or notified channel.','https://pmfby.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(4,'PM-KUSUM','Ministry of New & Renewable Energy','Farmer','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Farmer','18-21,21-35,35-60,60+','All','Programme supporting solar energy applications for the agricultural sector.','Eligible farmers and other permitted beneficiaries according to the applicable component.','Support for eligible solar pumps and renewable-energy installations.','Identity proof, land or pump documents, bank details and implementing-agency documents.','Apply through the designated state implementing agency.','https://pmkusum.mnre.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(5,'PM Vishwakarma','Ministry of Micro, Small & Medium Enterprises','Skill & Employment','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Worker,Business','18-21,21-35,35-60,60+','All','Support programme for artisans and craftspeople working with traditional tools and skills.','Eligible artisans belonging to the notified traditional trades and meeting scheme conditions.','Skill training, toolkit incentive, concessional credit, digital transaction incentive and marketing support.','Aadhaar, mobile number and documents required during registration and verification.','Register through the PM Vishwakarma system and prescribed verification process.','https://pmvishwakarma.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(6,'Pradhan Mantri MUDRA Yojana','Ministry of Finance','Financial','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Business,Worker','18-21,21-35,35-60,60+','Below 1 Lakh,1-3 Lakh,3-6 Lakh,Above 6 Lakh','Credit support for eligible non-farm micro and small business activities.','Eligible individuals and enterprises seeking permitted business or working-capital finance.','MUDRA loan support through applicable loan categories.','Identity proof, address proof, business documents and lender-required records.','Apply through a participating bank or financial institution.','https://www.myscheme.gov.in/schemes/pradhan-mantri-mudra-yojana',NULL,'Active','2026-09-03 13:36:21'),(7,'Prime Minister\'s Employment Generation Programme (PMEGP)','Ministry of Micro, Small & Medium Enterprises','Skill & Employment','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Business,Unemployed,Worker','21-35,35-60','Below 1 Lakh,1-3 Lakh,3-6 Lakh,Above 6 Lakh','Credit-linked support for setting up eligible new micro enterprises in the non-farm sector.','Eligible individuals and organizations meeting PMEGP conditions.','Margin-money subsidy linked to eligible bank-financed projects.','Identity proof, project report, bank documents and other prescribed records.','Apply through the official PMEGP e-portal.','https://www.kviconline.gov.in/pmegpeportal/',NULL,'Active','2026-09-03 13:36:21'),(8,'PM Street Vendor\'s AtmaNirbhar Nidhi (PM SVANidhi)','Ministry of Housing & Urban Affairs','Financial','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Business,Worker','18-21,21-35,35-60,60+','Below 1 Lakh,1-3 Lakh,3-6 Lakh,Above 6 Lakh','Working-capital support scheme for eligible street vendors.','Street vendors meeting the scheme\'s identification and verification requirements.','Working-capital loans, interest subsidy for timely repayment and digital transaction incentives subject to scheme rules.','Identity proof, vending-related documents, bank details and required local-body records.','Apply through the PM SVANidhi portal or participating lending channel.','https://pmsvanidhi.mohua.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(9,'PM Formalisation of Micro Food Processing Enterprises (PMFME)','Ministry of Food Processing Industries','Business','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Business,Farmer,Worker,Homemaker','21-35,35-60,60+','Below 1 Lakh,1-3 Lakh,3-6 Lakh,Above 6 Lakh','Support for formalisation and upgrading of eligible micro food-processing enterprises.','Eligible individual units and groups meeting the scheme guidelines.','Credit-linked capital support and other assistance under the scheme.','Identity proof, bank details, business records and project documents.','Apply through the prescribed PMFME and state implementation process.','https://pmfme.mofpi.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(10,'Pradhan Mantri Shram Yogi Maan-dhan (PM-SYM)','Ministry of Labour & Employment','Social Welfare','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Worker,Homemaker,Unemployed','18-21,21-35','Below 1 Lakh,1-3 Lakh','Voluntary contributory pension scheme for eligible unorganised workers.','Unorganised workers aged 18–40 meeting the scheme income and exclusion conditions.','Guaranteed monthly pension of ₹3,000 after age 60, subject to scheme rules.','Aadhaar, savings or Jan-Dhan account and mobile number.','Register through the Maandhan system or Common Service Centre.','https://maandhan.in/',NULL,'Active','2026-09-03 13:36:21'),(11,'PM-Kisan Maandhan Yojana','Ministry of Agriculture & Farmers Welfare','Farmer','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Farmer','18-21','Below 1 Lakh,1-3 Lakh','Voluntary contributory pension scheme for eligible small and marginal farmers.','Eligible small and marginal farmers in the prescribed age range and subject to exclusions.','Pension support after attaining 60 years according to scheme conditions.','Aadhaar, bank account and farmer-related details.','Register through Common Service Centres or the prescribed Maandhan process.','https://maandhan.in/',NULL,'Active','2026-09-03 13:36:21'),(12,'Pradhan Mantri Jan-Dhan Yojana (PMJDY)','Department of Financial Services, Ministry of Finance','Financial','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Student,Farmer,Worker,Homemaker,Business,Unemployed','Below 18,18-21,21-35,35-60,60+','All','National financial-inclusion programme providing access to basic banking services.','Eligible persons can open a basic savings bank deposit account subject to KYC requirements.','Basic bank account, RuPay card and access to linked financial services subject to conditions.','KYC and officially accepted identity/address documents.','Visit a participating bank branch or Business Correspondent outlet.','https://www.pmjdy.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(13,'Pradhan Mantri Jeevan Jyoti Bima Yojana (PMJJBY)','Department of Financial Services','Insurance','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Student,Farmer,Worker,Homemaker,Business,Unemployed','18-21,21-35,35-60','All','Low-cost life insurance scheme for eligible bank and post-office account holders.','Eligible account holders aged 18–50 can enroll subject to scheme conditions.','Life insurance cover of ₹2 lakh subject to the scheme terms.','Bank or post-office account details and KYC information.','Enroll through a participating bank or post office.','https://www.jansuraksha.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(14,'Pradhan Mantri Suraksha Bima Yojana (PMSBY)','Department of Financial Services','Insurance','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Student,Farmer,Worker,Homemaker,Business,Unemployed','18-21,21-35,35-60,60+','All','Affordable accident-insurance scheme for eligible account holders.','Eligible participating bank or post-office account holders aged 18–70.','Accident insurance benefits subject to scheme conditions.','Bank or post-office account details and KYC information.','Enroll through a participating bank or post office.','https://www.jansuraksha.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(15,'Atal Pension Yojana (APY)','Pension Fund Regulatory and Development Authority','Social Welfare','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Student,Farmer,Worker,Homemaker,Business,Unemployed','18-21,21-35','All','Pension scheme for eligible citizens with a savings bank or post-office account.','Eligible citizens aged 18–40 meeting current APY conditions.','Guaranteed minimum pension options after age 60 subject to scheme conditions.','Savings account details and KYC documents.','Enroll through the bank or post office holding the account.','https://www.pfrda.org.in/',NULL,'Active','2026-09-03 13:36:21'),(16,'Ayushman Bharat – PM-JAY','National Health Authority','Health','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Student,Farmer,Worker,Homemaker,Business,Unemployed','Below 18,18-21,21-35,35-60,60+','Below 1 Lakh,1-3 Lakh,3-6 Lakh,Above 6 Lakh','Government-funded health assurance programme for eligible beneficiaries.','Core PM-JAY eligibility is based on the government\'s prescribed beneficiary databases and rules. Separate senior-citizen coverage applies to citizens aged 70 years and above under the current expansion.','Up to ₹5 lakh per family per year for eligible beneficiaries subject to scheme rules.','Identity proof and beneficiary-verification information.','Check eligibility through the official PM-JAY/NHA system or participating facility.','https://pmjay.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(17,'Pradhan Mantri Ujjwala Yojana (PMUY)','Ministry of Petroleum & Natural Gas','Women','Women','All','Female','Student,Farmer,Worker,Homemaker,Business,Unemployed','21-35,35-60,60+','Below 1 Lakh,1-3 Lakh','LPG connection support for eligible adult women from poor households.','Adult woman aged 18 or above from an eligible poor household with no other LPG connection in the household.','Eligible LPG connection support and specified scheme benefits.','KYC, Aadhaar, ration/family-composition documents and bank details as required.','Apply through an LPG distributor or the official PMUY system.','https://www.pmuy.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(18,'PM Surya Ghar: Muft Bijli Yojana','Ministry of New & Renewable Energy','Energy','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Student,Farmer,Worker,Homemaker,Business,Unemployed','18-21,21-35,35-60,60+','All','Residential rooftop-solar programme supporting eligible households.','Residential electricity consumers satisfying the programme requirements.','Central financial assistance for eligible residential rooftop solar installations.','Electricity connection details, identity proof and bank information.','Apply through the national rooftop-solar portal.','https://pmsuryaghar.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(19,'Pradhan Mantri Awas Yojana – Urban 2.0','Ministry of Housing & Urban Affairs','Housing','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Student,Farmer,Worker,Homemaker,Business,Unemployed','18-21,21-35,35-60,60+','Below 1 Lakh,1-3 Lakh,3-6 Lakh,Above 6 Lakh','Housing support programme for eligible urban families without a pucca house.','Eligible EWS, LIG and MIG urban families satisfying PMAY-U 2.0 conditions.','Housing assistance through the applicable PMAY-U 2.0 vertical.','Aadhaar, income documents, address and property-related documents as applicable.','Apply through the PMAY-U 2.0 process and participating local authority.','https://pmay-urban.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(20,'Pradhan Mantri Awaas Yojana – Gramin (PMAY-G)','Ministry of Rural Development','Housing','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Student,Farmer,Worker,Homemaker,Business,Unemployed','18-21,21-35,35-60,60+','Below 1 Lakh,1-3 Lakh','Rural housing assistance for eligible households without adequate housing.','Eligibility is determined through the prescribed rural-housing identification and selection criteria.','Financial assistance for construction of an eligible pucca house.','Aadhaar, bank account and household/land documents as required.','Through Gram Panchayat and the prescribed implementation process.','https://pmayg.nic.in/',NULL,'Active','2026-09-03 13:36:21'),(21,'Sukanya Samriddhi Account','Department of Economic Affairs, Ministry of Finance','Women','Women','All','Female','Student','Below 18','All','Long-term savings account scheme for the future education and permitted needs of a girl child.','Account can be opened for an eligible girl child below 10 years by a parent or legal guardian.','Government-notified interest and applicable tax benefits subject to current rules.','Girl child birth certificate and guardian KYC/address documents.','Open through eligible post offices or participating banks.','https://www.indiapost.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(22,'Pradhan Mantri Matru Vandana Yojana (PMMVY)','Ministry of Women & Child Development','Women','Women','All','Female','Homemaker,Worker,Business,Unemployed','18-21,21-35,35-60','Below 1 Lakh,1-3 Lakh','Maternity benefit scheme providing financial support to eligible pregnant and lactating women.','Eligible women meeting the current PMMVY beneficiary and category conditions.','Maternity benefit paid according to the applicable scheme instalments and conditions.','Aadhaar, bank/post-office account and pregnancy/child-related documents.','Apply through the prescribed Anganwadi or government process.','https://www.spniwcd.wcd.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(23,'Central Sector Scheme of Scholarship for College and University Students','Department of Higher Education, Ministry of Education','Education','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Student','18-21,21-35','Below 1 Lakh,1-3 Lakh,3-6 Lakh,Above 6 Lakh','Merit-based scholarship support for eligible college and university students.','Students must meet the applicable academic, income and other scheme conditions.','Scholarship support for eligible students according to the scheme guidelines.','Marksheets, income certificate, bank account and category documents where required.','Apply through the National Scholarship Portal when the application window is open.','https://scholarships.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(24,'PM Young Achievers Scholarship Award Scheme for Vibrant India (PM-YASASVI)','Department of Social Justice & Empowerment','Education','OBC','All','Male,Female,Other','Student','18-21,21-35','Below 1 Lakh,1-3 Lakh,3-6 Lakh','Educational support scheme for eligible OBC, EBC and DNT students through applicable components.','Students meeting the applicable category, income, academic and educational-level conditions.','Scholarship and other educational support under applicable components.','Academic records, income certificate and category certificate.','Apply through the prescribed scholarship application system.','https://socialjustice.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(25,'National Apprenticeship Promotion Scheme (NAPS)','Ministry of Skill Development & Entrepreneurship','Skill & Employment','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Student,Worker,Unemployed','18-21,21-35,35-60','All','Programme promoting apprenticeship and industry-based skill training.','Eligible apprentices and participating establishments must meet apprenticeship requirements.','Apprenticeship training and specified government support under applicable rules.','Identity proof, educational records and apprenticeship registration details.','Register and apply through Apprenticeship India.','https://www.apprenticeshipindia.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(26,'Mahatma Gandhi National Rural Employment Guarantee Scheme (MGNREGS)','Ministry of Rural Development','Employment','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Worker,Farmer,Unemployed,Homemaker','18-21,21-35,35-60,60+','Below 1 Lakh,1-3 Lakh,3-6 Lakh,Above 6 Lakh','Rural employment programme providing guaranteed wage employment to eligible rural households.','Adult members of rural households willing to undertake unskilled manual work, subject to the Act and programme rules.','Wage employment and livelihood support through approved rural works.','Job card and household/residence-related details as required.','Register through the Gram Panchayat or prescribed state MGNREGA process.','https://nrega.nic.in/',NULL,'Active','2026-09-03 13:36:21'),(27,'Deendayal Antyodaya Yojana – National Rural Livelihoods Mission (DAY-NRLM)','Ministry of Rural Development','Livelihood','General,SC/ST,OBC,Minority,Women','All','Female','Homemaker,Business,Worker,Unemployed','21-35,35-60,60+','Below 1 Lakh,1-3 Lakh','Livelihood programme supporting rural poor households through self-help groups and livelihood opportunities.','Eligible rural households and members participating through the prescribed self-help-group and state mechanisms.','Self-help-group support, financial inclusion, skills and livelihood assistance.','Identity proof, bank details and SHG-related documents as required.','Approach the local rural livelihoods mission or SHG network.','https://aajeevika.gov.in/',NULL,'Active','2026-09-03 13:36:21'),(28,'Deendayal Antyodaya Yojana – National Urban Livelihoods Mission (DAY-NULM)','Ministry of Housing & Urban Affairs','Livelihood','General,SC/ST,OBC,Minority,Women','All','Male,Female,Other','Worker,Business,Unemployed,Homemaker','18-21,21-35,35-60,60+','Below 1 Lakh,1-3 Lakh,3-6 Lakh','Urban livelihood programme supporting skill development, self-employment and vulnerable urban households.','Urban poor and other eligible beneficiaries according to the applicable programme components.','Skill training, self-employment and livelihood support under applicable components.','Identity proof, address proof and programme-specific documents.','Apply through the urban local body or designated DAY-NULM channel.','https://nulm.gov.in/',NULL,'Active','2026-09-03 13:36:21');
