DROP TABLE IF EXISTS `women_government_schemes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `women_government_schemes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `scheme_name` varchar(255) NOT NULL,
  `scheme_level` varchar(50) NOT NULL DEFAULT 'Central',
  `category` varchar(100) NOT NULL,
  `description` text,
  `eligibility` text,
  `benefits` text,
  `documents` text,
  `application_method` text,
  `official_link` varchar(500) DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'Active',
  `eligibility_tags` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

