INSERT INTO `women_government_schemes` VALUES (1,'One Stop Centre (OSC)','Central','Safety & Protection','One Stop Centres provide integrated support and assistance to women affected by violence or in distress.','Women affected by violence or in distress|Support is available irrespective of the place where the woman lives, subject to local service arrangements','Medical assistance|Legal assistance|Psychological and counselling support|Police assistance|Temporary shelter|Help in accessing other support services','Identity proof if available|Case-related documents if available','Approach the nearest One Stop Centre or seek assistance through the Women Helpline.','https://www.spniwcd.wcd.gov.in/one-stop-centre-header','Active','category','2026-09-02 08:46:42'),(2,'Women Helpline (181)','Central','Safety & Protection','A universal toll-free helpline providing information, assistance and support to women in distress and women seeking information about government schemes and services.','Women in distress|Women seeking information or support related to women-focused government schemes and services|A person calling on behalf of a woman may also seek assistance','Information and support regarding women-focused schemes and services|Assistance and referral for women in distress|Connection to appropriate support services','No documents are generally required for an initial helpline enquiry','Call 181 for assistance. Emergency situations can be referred to emergency response services.','https://www.spniwcd.wcd.gov.in/help/faqs','Active','category','2026-09-02 08:46:42'),(3,'Beti Bachao Beti Padhao (BBBP)','Central','Education','A national initiative under Mission Shakti focused on improving the value, protection, education and empowerment of girls and promoting positive social and behavioural change.','Girls and women benefit through programme activities|Implementation is through convergence and awareness activities rather than a universal individual cash benefit','Awareness and behavioural-change activities|Promotion of girls\' education|Support for improving the survival, protection and development of girls|Convergence with relevant government programmes','Generally no individual application documents because BBBP is primarily a programme for awareness, convergence and institutional action','Participate through local government departments, educational institutions and district-level programmes implementing BBBP activities.','https://www.spniwcd.wcd.gov.in/beti-bachao-beti-padhao','Active','age;category','2026-09-02 08:46:42'),(4,'Nari Adalat','Central','Safety & Protection','A women\'s collective mechanism under Mission Shakti intended to facilitate alternative grievance redressal and promote gender justice in families and society.','Women seeking assistance in appropriate petty disputes, harassment, rights or entitlement-related matters|Coverage and implementation depend on the state and local programme arrangements','Alternative grievance redressal support|Facilitation of dialogue and settlement in suitable matters|Support for gender justice and awareness of women\'s rights','Documents depend on the grievance and local implementation process','Approach the relevant district or state women and child development authority or implementing Nari Adalat.','https://www.spniwcd.wcd.gov.in/nari-adalat','Active','category','2026-09-02 08:46:42'),(5,'Shakti Sadan','Central','Safety & Protection','An integrated relief and rehabilitation home under Mission Shakti for women in difficult circumstances, including women affected by destitution and trafficking.','Women in distress or difficult circumstances|Women requiring shelter and rehabilitation support|Women affected by trafficking, subject to the programme\'s admission and referral process','Shelter|Food and clothing|Counselling|Primary health support|Vocational training|Rehabilitation and reintegration support|Linkages to other services','Identity or case-related documents where available|Additional documents may be requested by the implementing authority','Approach the nearest Shakti Sadan through the concerned district/state authority or referral service.','https://www.spniwcd.wcd.gov.in/shakti-sadan/brief','Active','category','2026-09-02 08:46:42'),(6,'Sakhi Niwas - Working Women Hostel','Central','Social Welfare','A Mission Shakti component providing safe and affordable accommodation for working women and certain eligible women undergoing job training.','Working women meeting the programme conditions|Certain women undergoing job training may also be eligible|Income limits and other admission conditions apply according to the scheme guidelines and local facility','Safe accommodation|Affordable residence|Security arrangements|Day-care facility for children where available','Identity proof|Employment or training proof|Income-related documents as required by the hostel','Contact the nearest operational Sakhi Niwas or the concerned state/district authority to check availability and admission procedure.','https://www.spniwcd.wcd.gov.in/sakhi-niwas-working-women-hostel','Active','income;category','2026-09-02 08:46:42'),(7,'Pradhan Mantri Matru Vandana Yojana (PMMVY)','Central','Financial Assistance','A maternity benefit scheme under Mission Shakti providing financial assistance to eligible pregnant and lactating women.','Eligibility is available to women belonging to specified socially or economically disadvantaged categories under the scheme guidelines|Examples include women with SC/ST status, BPL ration card, PMJAY or e-Shram beneficiaries, MGNREGA Job Card holders and certain women from families meeting the prescribed income condition','₹5,000 for the first living child in two instalments subject to conditions|₹6,000 for a second living child when the second child is a girl, subject to the scheme conditions|Payment is made through DBT','Aadhaar|Aadhaar-linked bank or post-office account details|Pregnancy and antenatal-care records|Eligibility proof as applicable|Birth and immunisation information as required','Apply through the PMMVY portal or obtain assistance from the nearest Anganwadi Worker or ASHA Worker.','https://pmmvy.wcd.gov.in/','Active','income;age;category','2026-09-02 08:46:42'),(8,'Palna - Crèche Services','Central','Social Welfare','A Mission Shakti component providing safe and quality crèche care for young children to support childcare and women\'s participation in work and other activities.','Children aged 6 months to 6 years|Local enrolment and availability conditions apply','Safe childcare|Nutrition support|Health check-ups and immunisation convergence|Early stimulation|Pre-school education for children aged 3 to 6 years','Child age or birth record|Other local enrolment documents where required','Contact the nearest Anganwadi-cum-Crèche or Stand-alone Crèche operating under Palna.','https://www.spniwcd.wcd.gov.in/palna','Active','age','2026-09-02 08:46:42'),(9,'National Hub for Empowerment of Women (NHEW)','Central','Social Welfare','A Mission Shakti component that supports convergence, coordination and awareness so women can access government schemes, services and entitlements.','Women and girls seeking information and assistance regarding government schemes and services|Implementation is through national, state and district-level hubs','Information about women-focused schemes and services|Convergence and coordination among departments|Assistance in accessing available government services|Awareness and empowerment support','Usually no individual application document is required for information and referral support','Approach the relevant state or district Hub for Empowerment of Women or women and child development authority.','https://www.spniwcd.wcd.gov.in/detail-mission-shakti','Active','category','2026-09-02 08:46:42'),(10,'Sukanya Samriddhi Account (SSA)','Central','Education','A Government of India small savings scheme designed for the long-term financial security of a girl child.','Account can be opened for a girl child who has not yet attained 10 years of age|The account is opened by a parent or legal guardian|The girl child must be an eligible resident Indian under the scheme rules','Government-backed savings account for the girl child|Long-term savings for education and future needs|Interest is provided according to the notified government rate|Tax benefits are available subject to applicable income-tax rules','Birth certificate of the girl child|Identity and address proof of parent or guardian|KYC documents as required by the authorised bank or post office','Open the account through an authorised bank branch or India Post office offering Sukanya Samriddhi accounts.','https://www.indiapost.gov.in/','Active','age;category','2026-09-02 08:55:22'),(11,'Pradhan Mantri Ujjwala Yojana (PMUY)','Central','Financial Assistance','A government scheme providing LPG connections to eligible adult women from poor households.','Applicant must be a woman aged 18 years or above|Applicant must belong to an eligible poor household|There must be no other LPG connection from any oil marketing company in the same household','Security-deposit-free LPG connection|No installation charges for the connection package|LPG cylinder and regulator|Free first refill(s) and a two-burner stove as specified by the scheme','KYC application form|Aadhaar of applicant|Ration card or family-composition document|Aadhaar of adult family members appearing in the family document|Bank account details|Deprivation declaration','Apply through an LPG distributor or through the official online PMUY application facility.','https://www.pmuy.gov.in/','Active','income;age;category','2026-09-02 08:55:22'),(12,'Mukhyamantri Mazi Ladki Bahin Yojana','State - Maharashtra','Financial Assistance','A Maharashtra Government women-focused welfare scheme providing financial support to eligible women in the state.','Eligible women residing in Maharashtra|Age and family-income conditions apply according to the current Maharashtra Government scheme rules|Other prescribed conditions must be satisfied','Direct financial assistance to eligible women|Support for women\'s economic and social well-being','Aadhaar|Domicile or Maharashtra residence proof where required|Bank account details|Income and other eligibility documents as prescribed by the Maharashtra Government','Apply through the official Maharashtra Government application process or designated portal/service centre.','https://womenchild.maharashtra.gov.in/en/','Active','income;age;category','2026-09-02 08:55:22'),(13,'Lek Ladki Yojana','State - Maharashtra','Education','A Maharashtra Government scheme for the empowerment, education, health and overall development of eligible girl children.','Applicable to one or two girl children born on or after 1 April 2023 in eligible yellow or orange ration-card families|Beneficiary family must be a resident of Maharashtra|Additional conditions apply for certain second-child and family-planning situations','Financial assistance in stages from birth to 18 years|₹5,000 after birth|₹6,000 on admission to Class 1|₹7,000 on admission to Class 6|₹8,000 on admission to Class 11|₹75,000 after completing 18 years subject to scheme conditions','Birth certificate of the girl child|Ration card|Maharashtra residence documents|Bank account details|Family-planning certificate where required|Other documents prescribed by the implementing authority','Apply through the concerned Anganwadi or Women and Child Development implementation system in Maharashtra as prescribed for the scheme.','https://zpthane.maharashtra.gov.in/en/women-and-child-development-department/','Active','age;income;category','2026-09-02 08:55:22'),(14,'Mahila Coir Yojana (MCY)','Central','Entrepreneurship','A women-centric self-employment programme of the Coir Board aimed at providing sustainable rural livelihoods through coir yarn spinning and related activities.','Women interested in coir-related self-employment and eligible under the Coir Board programme guidelines|Training and participation requirements apply according to the programme rules','Skill training in coir yarn spinning|Support for women\'s self-employment|Assistance aimed at creating sustainable rural livelihoods|Stipendiary support may be available for eligible training or promotional activities as per programme provisions','Identity proof|Address or residence proof|Bank details|Application or training documents required by the Coir Board','Approach the nearest Coir Board field office or authorised training centre for programme details and application.','https://coirboard.gov.in/','Active','category','2026-09-02 08:55:22'),(15,'AICTE Pragati Scholarship Scheme for Girl Students','Central','Education','A scholarship scheme implemented by AICTE to support girl students pursuing approved technical diploma or degree programmes.','Girl students admitted to an AICTE-approved technical diploma or degree programme through the prescribed admission process|Eligibility is subject to the scheme guidelines and the applicable academic year|Family income and other prescribed conditions apply','Financial assistance for eligible girl students pursuing technical education|Scholarship support is provided through Direct Benefit Transfer subject to scheme rules|Scholarship is available for eligible diploma and degree students','Academic qualification marksheet or certificate|Family income certificate in the prescribed format|Admission or institute-related documents|Tuition fee receipt where applicable|Aadhaar details|Aadhaar-seeded bank account details|Other documents prescribed by AICTE','Apply online through the National Scholarship Portal during the application period and complete institute and government verification as required.','https://scholarships.gov.in/','Active','income;category','2026-09-02 08:58:08');
/*!40000 ALTER TABLE `women_government_schemes` ENABLE KEYS */;
