INSERT INTO `women_legal_aid_helplines` VALUES (1,'bi-telephone-fill','#db2777','Women Helpline (181)','24/7 toll-free helpline providing support and assistance to women in distress.','Women facing violence, harassment, abuse or other situations requiring support.','181 (Toll Free)','https://spniwcd.wcd.gov.in/women-helpline','Women Helpline 181 provides support to women in distress and can connect them with appropriate emergency and support services.','2026-09-03 09:54:13'),(2,'bi-shield-fill-check','#4f46e5','National Legal Services Authority (NALSA)','Free legal aid, legal advice and assistance for eligible persons.','Women are eligible for free legal services regardless of income.','15100 (Toll Free)','https://nalsa.gov.in/','NALSA provides free legal assistance through Legal Services Institutions at national, state, district and taluka levels. Women are among the categories specifically eligible for free legal aid.','2026-09-03 09:54:13'),(3,'bi-exclamation-triangle-fill','#ef4444','Emergency Response Support System (112)','Pan-India emergency response service for immediate assistance.','Anyone facing an emergency requiring police, fire, health or other emergency assistance.','112 (Emergency)','https://112.gov.in/','The 112 Emergency Response Support System provides a single emergency number for immediate assistance across India.','2026-09-03 09:54:13'),(4,'bi-laptop-fill','#7c3aed','National Cyber Crime Reporting Portal','Online reporting of cyber crimes, including cyber crimes against women and children.','Anyone affected by a cybercrime. The portal also provides anonymous reporting for specified categories.','1930 for Cyber Financial Fraud','https://www.cybercrime.gov.in/','The National Cyber Crime Reporting Portal allows citizens to report cybercrime online. For immediate reporting of cyber financial fraud, call the national cybercrime helpline 1930.','2026-09-03 09:54:13'),(5,'bi-house-heart-fill','#10b981','One Stop Centre (Sakhi)','Integrated support for women affected by violence.','Women affected by violence, including domestic and sexual violence.','Contact the nearest One Stop Centre','https://spniwcd.wcd.gov.in/one-stop-centre-header/brief','One Stop Centres provide integrated support such as medical assistance, legal aid, counselling, temporary shelter and police facilitation.','2026-09-03 09:54:13'),(6,'bi-bank2','#f59e0b','National Commission for Women (NCW)','Grievance support and assistance for issues concerning women and violence against women.','Women seeking assistance or wishing to report grievances concerning violations of womens rights.','14490 (24x7 Violence Against Women Helpline)','https://ncwapps.nic.in/','The National Commission for Women provides a 24x7 helpline for issues related to violence against women and handles grievances through its complaint and investigation system.','2026-09-03 09:54:13'),(7,'bi-people-fill','#06b6d4','Maharashtra State Commission for Women','State-level support, counselling and legal guidance for women in Maharashtra.','Women residing in Maharashtra seeking support regarding women-related issues.','022-26592707 / 155209','https://www.mscw.org.in/','The Maharashtra State Commission for Women is a statutory body that works on womens rights, investigates complaints and provides counselling and free legal advice to women in need.','2026-09-03 09:54:13'),(8,'bi-shield-lock-fill','#f97316','Child Helpline (1098)','24/7 emergency outreach and support service for children in difficult circumstances.','Children in distress and people concerned about the safety or protection of a child.','1098 (Toll Free)','https://spniwcd.wcd.gov.in/child-helpline','Child Helpline 1098 operates under Mission Vatsalya and is integrated with the 112 Emergency Response Support System. It connects children in crisis with emergency, care and rehabilitation services.','2026-09-03 09:54:13');
