  `right_title` varchar(255) NOT NULL,
  `right_description` text,
  `key_points` text,
  `law` varchar(500) DEFAULT NULL,
  `action` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
