CREATE TABLE `workers` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `primary_skill` varchar(100) NOT NULL,
  `other_skills` text,
  `location` varchar(100) DEFAULT NULL,
  `area` varchar(100) DEFAULT NULL,
  `experience_years` int DEFAULT '0',
  `languages` varchar(255) DEFAULT NULL,
  `availability` varchar(50) DEFAULT NULL,
  `charges` varchar(100) DEFAULT NULL,
  `certifications` text,
  `previous_work_experience` text,
  `about` text,
  `services_offered` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `category_id` int DEFAULT NULL,
  `rating` decimal(2,1) DEFAULT '0.0',
  `review_count` int DEFAULT '0',
  `verified` tinyint(1) DEFAULT '0',
  `is_demo` tinyint(1) NOT NULL DEFAULT '0',
  `portfolio` text,
  `verification_status` enum('pending','approved','rejected') DEFAULT 'pending',
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `fk_worker_category` (`category_id`),
  CONSTRAINT `fk_worker_category` FOREIGN KEY (`category_id`) REFERENCES `job_categories` (`id`),
  CONSTRAINT `workers_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

